window.C5=window.C5||{};C5.science={"t":"বিজ্ঞান","ch":[{"no":1,"title":"অধ্যায় ১","q":{"mcq":[{"n":"ক","q":"জলজ উদ্ভিদের অনন্য বৈশিষ্ট্য কোনটি?","a":"খ) বায়ুকুঠুরি","o":["পাতা পুরু","বায়ুকুঠুরি","ফুল","কাঁটাযুক্ত"]},{"n":"খ","q":"মাংসাশী প্রাণীর প্রধান বৈশিষ্ট্য কোনটি?","a":"গ) তীক্ষ্ণ দাঁত","o":["দ্রুত গতি","বড়ো আকৃতি","তীক্ষ্ণ দাঁত","চর্বির স্তর"]},{"n":"গ","q":"শ্বাসমূল কোন উদ্ভিদে পাওয়া যায়?","a":"খ) সুন্দরী","o":["হিজল","সুন্দরী","পাকুড়","কচুরিপানা"]}],"blank":[{"n":"ক","q":"জলজ উদ্ভিদকে পানিতে ভেসে থাকতে সাহায্য করে ______।","a":"বায়ুকুঠুরি"},{"n":"খ","q":"তীব্র ঠান্ডায় প্রাণীর দেহকে গরম রাখে ______।","a":"চর্বিস্তর"},{"n":"গ","q":"ছায়াযুক্ত স্থানের একটি উদ্ভিদ হলো ______।","a":"ফার্ন"}],"short":[{"n":"ক","q":"জীবের আবাসস্থল বলতে কী বোঝায়?","a":"জীবের আবাসস্থল হলো সেই পরিবেশ বা স্থান, যেখানে কোনো জীব স্বাভাবিকভাবে বাস করে, খাদ্য পায়, বংশবিস্তার করে এবং নিরাপদে থাকতে পারে।"},{"n":"খ","q":"স্বাদু পানির পরিবেশে কী ধরনের প্রাণী ও উদ্ভিদ থাকে?","a":"স্বাদু পানির পরিবেশে সাধারণত-\nপ্রাণী: মাছ, ব্যাঙ, শামুক, কাঁকড়া, পোকামাকড় ইত্যাদি থাকে।\nউদ্ভিদ: শাপলা, পদ্ম, কচুরিপানা, জলঘাস ইত্যাদি জন্মায়।"},{"n":"গ","q":"জলজ প্রাণীতে কী ধরনের অভিযোজন ঘটে?","a":"জলজ প্রাণীতে যে অভিযোজনগুলো দেখা যায়-\nদেহ নৌকার মতো আকৃতির হয়, যাতে সহজে সাঁতার কাটতে পারে।\nপাখনা বা ঝিল্লিযুক্ত পা থাকে।\nগিলের মাধ্যমে (মরষষং) শ্বাস নিতে পারে।\nদেহে চর্বি বা বায়ুথলি থাকে, যা ভেসে থাকতে সাহায্য করে।"}],"essay":[{"n":"ক","q":"স্থলজ উদ্ভিদ ও প্রাণীর বৈশিষ্ট্যগুলো কী কী?","a":"স্থলজ উদ্ভিদের বৈশিষ্ট্য:\nএদের দেহ দৃঢ় ও শক্তিশালী কাণ্ড দ্বারা স্থির থাকে।\nপাতা সাধারণত পুরু ও শক্ত হয়, যাতে অতিরিক্ত পানি ক্ষয় না হয়।\nশিকড় দীর্ঘ ও বিস্তৃত থাকে, যা মাটি থেকে পানি ও পুষ্টি শোষণ করে।\nপর্যাপ্ত আলো গ্রহণের জন্য পাতার আকার ও বিন্যাস উপযোগী।\nপরিবেশ অনুযায়ী অভিযোজন থাকে-যেমন মরুভূমির উদ্ভিদে কাঁটা, বনাঞ্চলের উদ্ভিদে বড় পাতা।\nস্থলজ প্রাণীর বৈশিষ্ট্য:\nশ্বাস নেওয়ার জন্য ফুসফুস ব্যবহার করে।\nচলাচলের জন্য পা, ডানা বা দেহের বিশেষ গঠন থাকে।\nপানি সংরক্ষণের ক্ষমতা বেশি (বিশেষ করে মরুভূমির প্রাণীতে)।\nপরিবেশের তাপমাত্রা অনুযায়ী শরীরের তাপমাত্রা নিয়ন্ত্রণ করতে পারে।\nখাদ্য সংগ্রহ ও শত্রু থেকে রক্ষা পেতে বিভিন্ন ধরনের অভিযোজন দেখা যায়।"},{"n":"খ","q":"জলজ পরিবেশের উদ্ভিদ ও প্রাণীর বৈশিষ্ট্যগুলো উল্লেখ করি।","a":"জলজ উদ্ভিদের বৈশিষ্ট্য:\nদেহে বায়ুকুঠুরি থাকে, যা তাদের ভেসে থাকতে সাহায্য করে।\nশিকড় সাধারণত দুর্বল বা ছোট হয়, কারণ মাটিতে দৃঢ়ভাবে ধরার প্রয়োজন কম।\nপাতাগুলো চওড়া ও পাতলা হয়, যাতে পানির উপর ভেসে বাতাস পায়।\nপানির স্রোতের সাথে খাপ খাইয়ে নরম দেহগঠন থাকে।\nকয়েকটি উদ্ভিদ সম্পূর্ণ ডুবোজাত (যেমন জলঘাস), আবার কিছু আংশিক ভেসে থাকে (যেমন কচুরিপানা, শাপলা)।\nজলজ প্রাণীর বৈশিষ্ট্য:\nদেহ নৌকার মতো আকৃতির, যাতে সহজে সাঁতার কাটতে পারে।\nচলাচলের জন্য পাখনা বা ঝিল্লিযুক্ত পা থাকে।\nশ্বাস নেওয়ার জন্য গিল ব্যবহার করে (মাছ), কিছু প্রাণী ফুসফুস দিয়েও শ্বাস নেয় (ব্যাঙ)।\nদেহে চর্বি বা বায়ুথলি থাকে, যা ভেসে থাকতে সাহায্য করে।\nপানি থেকে অক্সিজেন গ্রহণ, শিকার ধরা ও স্রোত এড়িয়ে চলার মতো অভিযোজন থাকে।"},{"n":"গ","q":"সামুদ্রিক পরিবেশের প্রাণীদের অভিযোজনের ক্ষেত্রগুলো কী কী? উদাহরণসহ ব্যাখ্যা করি।","a":"জলজ পরিবেশের মধ্যে সবচেয়ে বিস্তীর্ণ ও বিশেষ পরিবেশ হলো সামুদ্রিক পরিবেশ। এই পরিবেশে পানি অত্যন্ত লবণাক্ত এবং পানির চাপ খুব বেশি, তাই এখানে বেঁচে থাকার জন্য প্রাণীদের বিভিন্ন ধরনের অভিযোজন ঘটে।\nসামুদ্রিক মাছের দেহ মাথা ও লেজের দিকে সরু এবং মধ্যভাগ চওড়া হয়। এ ধরনের দেহগঠন পানির মধ্যে দ্রুত চলাচল করতে সাহায্য করে। যেমন সামুদ্রিক মাছ-এর দেহের গঠন পানির স্রোত কমিয়ে দ্রুত সাঁতার কাটতে সাহায্য করে।\nপাখনা পানির মধ্যে সহজে চলাচল ও দিক পরিবর্তন করতে সাহায্য করে। যেমন হাঙর বা বড় সামুদ্রিক মাছ-লেজের পাখনা তাদের শক্তিশালী গতিবেগ দেয়।\nসামুদ্রিক স্তন্যপায়ী প্রাণীদের ফুসফুস থাকে এবং তারা দীর্ঘ সময় ধরে বাতাস জমা রেখে পানির নিচে থাকতে পারে। যেমন তিমি ও ডলফিন-দীর্ঘসময় ডুব দিয়ে থাকতে পারে কারণ তাদের ফুসফুসে বাতাস সঞ্চিত থাকে।\nসামুদ্রিক প্রাণীরা আলো, রং ও বিভিন্ন অঙ্গের সাহায্যে শিকার ধরতে বা আত্মরক্ষা করতে পারে। যেমন অক্টোপাস-রং পরিবর্তন করতে পারে, যা আত্মরক্ষায় সাহায্য করে।আবার বড় মাছ-তীক্ষ্ণ দাঁত দিয়ে শিকার ধরে।"}]}},{"no":2,"title":"অধ্যায় ২","q":{"mcq":[{"n":"ক","q":"জীবজগতে সকল শক্তির উৎস কী?","a":"ক) সূর্য","o":["সূর্য","সবুজ উদ্ভিদ","খাদ্য","বায়ু"]},{"n":"খ","q":"নিচের কোন উপাদানের জন্য উদ্ভিদ প্রাণীর ওপর নির্ভরশীল?","a":"খ) কার্বন ডাইঅক্সাইড","o":["অক্সিজেন","কার্বন ডাইঅক্সাইড","পানি","বংশবৃদ্ধি"]},{"n":"গ","q":"খাদ্যশৃঙ্খলে উৎপাদক কোনটি?","a":"খ) সবুজ উদ্ভিদ","o":["ছত্রাক","সবুজ উদ্ভিদ","পশুর খামার","কলকারখানা"]}],"blank":[{"n":"ক","q":"খাদ্যশৃঙ্খলে সবুজ উদ্ভিদকে বলা হয় ______।","a":"উৎপাদক"},{"n":"খ","q":"______ প্রাণী হলো প্রথম শ্রেণির খাদক।","a":"তৃণভোজী"},{"n":"গ","q":"উদ্ভিদের বীজের বিস্তরণে সাহায্য করে ______।","a":"পাখি"}],"short":[{"n":"ক","q":"উদ্ভিদ কীভাবে জড়বস্তুর ওপর নির্ভরশীল?","a":"উদ্ভিদ জড়বস্তুর ওপর নির্ভর করে কারণ-\nসূর্যালোক দিয়ে খাদ্য তৈরি করে।\nপানি দিয়ে পুষ্টি পরিবহন ও খাদ্য তৈরির কাজ করে।\nবায়ু থেকে কার্বন ডাইঅক্সাইড গ্রহণ করে।\nমাটি থেকে খনিজ লবণ ও পানি গ্রহণ করে।\nঅর্থাৎ উদ্ভিদ বাঁচতে ও খাদ্য তৈরি করতে জড়বস্তুর ওপর সম্পূর্ণভাবে নির্ভরশীল।"},{"n":"খ","q":"উদ্ভিদ বংশবৃদ্ধির জন্য প্রাণীর ওপর কীভাবে নির্ভরশীল?","a":"উদ্ভিদ বংশবৃদ্ধির জন্য প্রাণীর ওপর নির্ভরশীল-\nপরাগায়ণ: মৌমাছি, প্রজাপতি, পাখি ইত্যাদি ফুলে পরাগ ছড়িয়ে বংশবৃদ্ধিতে সাহায্য করে।\nবীজ ছড়ানো: পাখি, কাঠবিড়ালি ইত্যাদি প্রাণী বীজ ছড়িয়ে উদ্ভিদের বংশবৃদ্ধি ঘটায়।\nঅর্থাৎ প্রাণীরা উদ্ভিদের প্রজননে গুরুত্বপূর্ণ ভূমিকা রাখে।"},{"n":"গ","q":"নিকট-পরিবেশে দেখা যায় এমন একটি খাদ্যশৃঙ্খলের প্রবাহচিত্র তৈরি করি।","a":"নিকট-পরিবেশে দেখা যায় এমন একটি সাধারণ খাদ্যশৃঙ্খল-\nঘাস → পোকা → ব্যাঙ → সাপ। অথবা, ঘাস → গরু → মানুষ।"}],"essay":[{"n":"ক","q":"উদ্ভিদের ওপর মানুষ ও অন্যান্য প্রাণী কীভাবে নির্ভরশীল?","a":"উদ্ভিদের ওপর মানুষ এবং অন্যান্য প্রাণী নানা উপায়ে নির্ভরশীল। উদ্ভিদ পৃথিবীর সকল জীবের জন্য অক্সিজেনের প্রধান উৎস। মানুষ ও প্রাণীরা শ্বাস নেওয়ার জন্য যে অক্সিজেন ব্যবহার করে, উদ্ভিদ তা উৎপাদন করে। উদ্ভিদ খাদ্যেরও প্রধান উৎস। ফল, শাকসবজি, শস্যদানা, ডাল-এসব মানুষ সরাসরি উদ্ভিদ থেকে পায়। আবার অনেক প্রাণী উদ্ভিদ খেয়ে বেঁচে থাকে, ফলে প্রাণীদের টিকে থাকার জন্যও উদ্ভিদ অপরিহার্য।\nউদ্ভিদ শুধু খাদ্যই নয়, আশ্রয় ও বাসস্থানও দেয়। পাখি, পোকামাকড়, বানরসহ অনেক প্রাণী গাছে বাস করে। গাছপালা পরিবেশের তাপমাত্রা নিয়ন্ত্রণ করে, বায়ু পরিশোধন করে, মাটি রক্ষা করে এবং জীববৈচিত্র‍্য বজায় রাখে। মানুষ ঘরবাড়ি, আসবাবপত্র, কাগজ, ওষুধ, কাপড়সহ অনেক প্রয়োজনীয় জিনিস উদ্ভিদ থেকে সংগ্রহ করে। তাই বলা যায়, উদ্ভিদ ছাড়া মানুষ ও প্রাণী কোনোভাবেই বেঁচে থাকতে পারে না। উদ্ভিদ জীবজগতের ভিত্তি ও পরিবেশের সবচেয়ে গুরুত্বপূর্ণ উপাদান।"},{"n":"খ","q":"পরিবেশের উপাদানগুলোর ভারসাম্য রক্ষা করা প্রয়োজন কেন?","a":"পরিবেশের উপাদান-মাটি, পানি, বায়ু, আলো, তাপ, উদ্ভিদ ও প্রাণী-পরস্পরের সাথে ঘনিষ্ঠভাবে যুক্ত এবং একে অপরের ওপর নির্ভরশীল। এই উপাদানগুলোর যে কোনো একটি বেশি বা কম হয়ে গেলে পরিবেশের স্বাভাবিক ভারসাম্য নষ্ট হয়ে যায়। উদাহরণ হিসেবে বলা যায়-যদি তাপমাত্রা অত্যধিক বৃদ্ধি পায়, তাহলে খরা দেখা দিতে পারে, নদী-খাল শুকিয়ে যেতে পারে, ফসল নষ্ট হতে পারে। পানি দূষিত হলে জলজ প্রাণীর জীবন সংকটাপন্ন হয় এবং মানুষও বিশুদ্ধ পানি পায় না।\nবায়ু দূষিত হলে মানুষ এবং প্রাণীর স্বাস্থ্যের উপর বিরূপ প্রভাব পড়ে। উদ্ভিদ কমে গেলে অক্সিজেনের মাত্রা কমে যায়, কার্বন ডাই-অক্সাইড বেড়ে গিয়ে গরম বৃদ্ধি পায়। একইভাবে প্রাণী কমে গেলে খাদ্যশৃঙ্খল ভেঙে পড়ে, ফলে পরিবেশের ভারসাম্য নষ্ট হয়। তাই মাটি, পানি, বায়ু, আলো ও জীবজন্তুর মধ্যে একটি সঠিক সমন্বয় থাকা অত্যন্ত জরুরি। পরিবেশের ভারসাম্য রক্ষা না হলে পৃথিবীতে কোনো জীব স্বাভাবিকভাবে বেঁচে থাকতে পারবে না।"},{"n":"গ","q":"প্রাণী ও উদ্ভিদের পারস্পরিক নির্ভরতার আলোকে জীবজগতে শক্তির প্রবাহ বর্ণনা করি।","a":"জীবজগতে শক্তির প্রধান উৎস হলো সূর্য। সূর্যের আলো ব্যবহার করে উদ্ভিদ তাদের খাদ্য তৈরি করে, যাকে সালোকসংশ্লেষণ প্রক্রিয়া বলা হয়। এ কারণে উদ্ভিদকে উৎপাদক বলা হয়, কারণ তারা নিজের খাদ্য নিজে তৈরি করে এবং শক্তি সঞ্চয় করে। এই শক্তি পরে প্রাণীরা গ্রহণ করে। শাকাহারী প্রাণী উদ্ভিদ খেয়ে শক্তি পায়। এরপর মাংসাশী প্রাণী শাকাহারী প্রাণী খেয়ে সেই শক্তি নিজেদের দেহে সঞ্চয় করে। এইভাবে এক জীব থেকে আরেক জীবের মধ্যে শক্তির প্রবাহ ঘটে, যাকে খাদ্যশৃঙ্খল ও শক্তির প্রবাহ বলা হয়।\nপ্রবাহচিত্র: সূর্য → উদ্ভিদ → তৃণভোজী প্রাণী → মাংসাশী প্রাণী → মানুষ।\nএখানে প্রতিটি জীব আগের জীব থেকে শক্তি গ্রহণ করছে। এই পুরো প্রক্রিয়ায় উদ্ভিদ ও প্রাণীর পারস্পরিক নির্ভরতা স্পষ্টভাবে দেখা যায়। উদ্ভিদ না থাকলে শক্তির উৎসই থাকবে না। আবার প্রাণী না থাকলে খাদ্যশৃঙ্খল ভেঙে যাবে। তাই জীবজগতের প্রতিটি জীবই শক্তির প্রবাহে গুরুত্বপূর্ণ ভূমিকা পালন করে এবং পরস্পরের ওপর নির্ভর করে টিকে থাকে।"}]}},{"no":3,"title":"অধ্যায় ৩","q":{"mcq":[{"n":"ক","q":"নিচের কোনটি শর্করা জাতীয় খাদ্য?","a":"খ) আলু","o":["ডিম","আলু","মাখন","মৌসুমি ফল"]},{"n":"খ","q":"পাশের চিত্রের ফলমূলে নিচের কোনটি অধিক পরিমাণে থাকে?","a":"খ) ভিটামিন-সি","o":["ভিটামিন-বি","ভিটামিন-সি","ভিটামিন-ডি","ভিটামিন-কে"]},{"n":"গ","q":"কিউরিং পদ্ধতিতে খাদ্যশস্য-","a":"খ) কম তাপমাত্রায় অধিক ঠান্ডা স্থানে রাখা হয়","o":["রোদে রেখে শুকিয়ে নেওয়া হয়","কম তাপমাত্রায় অধিক ঠান্ডা স্থানে রাখা হয়","লবণ মিশিয়ে সংরক্ষণ করা হয়","চিনি, তেল, ভিনেগার মিশিয়ে রাখা হয়"]},{"n":"ঘ","q":"অনিয়মিত খাদ্যাভ্যাসের ফলে-","a":"ঘ) স্থূলতা ও বিষণ্নতা দেখা দিতে পারে","o":["রোগের সংক্রমণ হলেও দ্রুত সুস্থ হওয়া যায়","পাকস্থলীতে ক্ষত হওয়ার সম্ভাবনা কমে","মন সবসময় ভালো ও উৎফুল্ল থাকে","স্থূলতা ও বিষণ্নতা দেখা দিতে পারে"]}],"short":[{"n":"ক","q":"আমিষ জাতীয় খাদ্য গ্রহণ কেন প্রয়োজন?","a":"আমিষ জাতীয় খাদ্য দেহের বৃদ্ধি, গঠন ও মেরামতে সাহায্য করে। দেহের পেশী, রক্ত, ত্বক, নখ-চুল তৈরি করতে আমিষ অত্যন্ত প্রয়োজন। এছাড়া আমিষ রোগ প্রতিরোধ ক্ষমতা বাড়ায় এবং শরীরকে শক্তিশালী রাখে।"},{"n":"খ","q":"সুষম খাদ্য গ্রহণের উপকারিতা লেখ।","a":"সুষম খাদ্য দেহকে সুস্থ, সবল ও কর্মক্ষম রাখতে সাহায্য করে। এটি দেহের বৃদ্ধি ও বিকাশ ঘটায়, রোগ প্রতিরোধ ক্ষমতা বাড়ায় এবং শরীরের সব অঙ্গ-প্রত্যঙ্গ ঠিকভাবে কাজ করতে পারে। সুষম খাদ্য খেলে মনোযোগ বাড়ে ও পড়াশোনায় ভালো ফল পাওয়া যায়।"},{"n":"গ","q":"যথেষ্ট পরিমাণে আমিষ ও তেল সমৃদ্ধ খাবার খেলেও পুষ্টিহীনতা থাকতে পারে-কেন?","a":"কারণ শুধুমাত্র আমিষ ও তেল খেয়ে ভিটামিন, খনিজ লবণ, শর্করা ও আঁশের ঘাটতি পূরণ হয় না। একটি সুস্থ দেহের জন্য সব ধরনের পুষ্টি উপাদান প্রয়োজন। কোনো একটি উপাদান বেশি থাকলেও অন্যগুলো কম হলে দেহে পুষ্টিহীনতা দেখা দিতে পারে। তাই সুষম খাদ্য না খেলে পুষ্টির ঘাটতি থেকেই যায়।"}],"essay":[{"n":"ক","q":"খাদ্য সংরক্ষণ কাকে বলে? খাদ্য সংরক্ষণ গুরুত্বপূর্ণ কেন তা লেখ।","a":"খাদ্য সংরক্ষণ হলো এমন একটি প্রক্রিয়া যার মাধ্যমে খাদ্যকে নষ্ট হওয়া, পচে যাওয়া, জীবাণু বা পোকামাকড়ের আক্রমণ থেকে রক্ষা করে দীর্ঘসময় ভালো রাখা হয়। রোদে শুকানো, ফ্রিজে রাখা, লবণ বা চিনি মেশানো, আচার বানানো অথবা বায়ুরোধী পাত্রে রাখা-এসবই খাদ্য সংরক্ষণের বিভিন্ন পদ্ধতি।\nখাদ্য সংরক্ষণ গুরুত্বপূর্ণ কারণ-\nখাদ্য নষ্ট হওয়া থেকে রক্ষা পাওয়া যায়: সংরক্ষণ না করলে অনেক খাবার দ্রুত পচে যায়।\nদীর্ঘসময় খাদ্যের গুণমান বজায় থাকে: স্বাদ, রং ও পুষ্টিগুণ অক্ষুণ্ন থাকে।\nপ্রয়োজনের সময় খাদ্য পাওয়া যায়: মৌসুম শেষ হলেও সংরক্ষিত খাদ্য সহজে পাওয়া যায়।\nঅপচয় কমে: অতিরিক্ত খাদ্য সংরক্ষণ করা হলে নষ্ট হওয়ার সম্ভাবনা কমে।\nদুর্যোগের সময় খাদ্য নিরাপত্তা নিশ্চিত হয়: বন্যা-খরা বা জরুরি সময়ে সংরক্ষিত খাবার কাজে লাগে।\nবাজারে চাহিদা-সরবরাহ নিয়ন্ত্রণ হয়: খাদ্যের দাম স্থিতিশীল থাকে এবং সারা বছর খাদ্য পাওয়ার ব্যবস্থা থাকে।"},{"n":"খ","q":"নিয়মিত খাদ্যগ্রহণ কীভাবে আমাদের স্বাস্থ্য রক্ষায় ভূমিকা রাখে?","a":"নিয়মিত ও সঠিক সময়ে খাদ্যগ্রহণ শরীরের জন্য অত্যন্ত প্রয়োজনীয়। নির্দিষ্ট সময়ের ব্যবধানে খাবার খেলে দেহের হজম প্রক্রিয়া ঠিকভাবে কাজ করে এবং শক্তি সরবরাহ স্থির থাকে। নিয়মিত খাদ্যগ্রহণ-\nশরীরকে সুস্থ, সবল ও কর্মক্ষম রাখে।\nহজমশক্তি উন্নত করে: পেটের সমস্যা, গ্যাস বা অস্বস্তি কম হয়।\nদেহের বৃদ্ধি ও পুষ্টির চাহিদা পূরণ করে: বিশেষত শিশুদের জন্য নিয়মিত খাবার অত্যন্ত জরুরি।\nরোগ প্রতিরোধ ক্ষমতা বাড়ায়: দেহ জীবাণুর বিরুদ্ধে সহজে লড়তে পারে।\nমনোযোগ ও শেখার ক্ষমতা বাড়ায়: পড়াশোনা বা কাজের দক্ষতা বৃদ্ধি পায়।\nক্লান্তি, দুর্বলতা বা মাথা ঘোরা কম হয়: শক্তি স্থিরভাবে পাওয়া যায়।\nএইসব কারণে স্বাস্থ্য ভালো রাখতে নিয়মিত খাদ্যগ্রহণ খুবই গুরুত্বপূর্ণ।"},{"n":"গ","q":"কম খরচে সুষম খাদ্যতালিকা কীভাবে করা যায়?","a":"কম খরচে সুষম খাদ্যতালিকা তৈরি করা সম্ভব যদি আমরা স্থানীয় ও মৌসুমী খাদ্যকে গুরুত্ব দিই। সুশৃঙ্খলভাবে পরিকল্পনা করলে অল্প খরচেই পুষ্টিকর খাবার পাওয়া যায়। কম খরচে সুষম খাদ্যতালিকা করার উপায়-\nস্থানীয় ও মৌসুমী ফল-সবজি বেছে নেওয়া: এগুলো সস্তা এবং পুষ্টিকর।\nডাল ও শাকসবজি নিয়মিত খাওয়া: ডাল সস্তা উৎস হলেও ভালো আমিষ সরবরাহ করে।\nমাছের ছোট জাত ব্যবহার: ছোট মাছ যেমন মলা, কাঁচকি, রুইয়ের ছোট টুকরা-এগুলো সস্তা কিন্তু পুষ্টিকর।\nডিম সাশ্রয়ী আমিষ: সপ্তাহে ৩-৪ দিন ডিম খেলে পুষ্টির চাহিদা সহজে মেটে।\nঅতিরিক্ত তেল-চিনি এড়ানো: এগুলোর দাম বেশি এবং পুষ্টিগুণ কম।\nবাড়িতে খাবার রান্না করা: বাইরে খেলে ব্যয় বাড়ে এবং পুষ্টির ঘাটতি হতে পারে।\nমানসম্মত কার্বোহাইড্রেট বেছে নেওয়া: ভাত, রুটি, আলু-সুলভ এবং শক্তির ভালো উৎস।\nএকই খাদ্য বিভিন্নভাবে রান্না করে বৈচিত্র‍্য আনা: এতে পুষ্টি থাকে, খরচও কমে।\nএইভাবে পরিকল্পনা করলে খুব কম খরচেও সম্পূর্ণ সুষম খাদ্যতালিকা তৈরি করা যায়।"}]}},{"no":4,"title":"অধ্যায় ৪","q":{"mcq":[{"n":"ক","q":"বয়ঃসন্ধিকাল সাধারণত কোন সময় হতে শুরু হয়?","a":"গ) কৈশোর","o":["বাল্যকাল","শৈশবকাল","কৈশোর","যৌবনকাল"]},{"n":"খ","q":"বয়ঃসন্ধিকালে মেয়েদের মধ্যে নিচের কোন পরিবর্তনটি লক্ষ করা যায়?","a":"খ) শরীর কিছুটা ভারী হয়","o":["পেশি সুগঠিত হয়","শরীর কিছুটা ভারী হয়","গলার স্বর মোটা হয়","কাঁধ চওড়া হয়"]},{"n":"গ","q":"বয়ঃসন্ধিকালে পরিষ্কার-পরিচ্ছন্ন থাকা জরুরি, কারণ এতে-","a":"ক) শরীর রোগমুক্ত থাকে","o":["শরীর রোগমুক্ত থাকে","শারীরিক সৌন্দর্য বজায় থাকে","রাতে ভালো ঘুম হয়","মন ভালো থাকে"]}],"truefalse":[{"n":"১","q":"বয়ঃসন্ধিকালীন শারীরিক পরিবর্তন কোনো স্বাভাবিক পরিবর্তন নয়।","a":"অশুদ্ধ"},{"n":"২","q":"সাধারণত ছেলেদের বয়ঃসন্ধিকাল ৯ থেকে ১৫ বছর","a":"অশুদ্ধ"},{"n":"৩","q":"বাবা-মা অথবা বাসার বড়োদের সাথে বয়ঃসন্ধিকালীন পরিবর্তন নিয়ে আলোচনার প্রয়োজন নাই","a":"অশুদ্ধ"},{"n":"৪","q":"বয়ঃসন্ধিকালীন পরিবর্তনগুলো সকলের একই সময়ে বা একইভাবে হয় না","a":"শুদ্ধ"}],"short":[{"n":"১","q":"বয়ঃসন্ধিকালে শরীর ও মন সুস্থ রাখার উপায়গুলো কী কী?","a":"বয়ঃসন্ধিকালে শরীর ও মন সুস্থ রাখার উপায়গুলো নিচে উল্লেখ করা হলো:\nসুষম ও পুষ্টিকর খাদ্য খাওয়া\nনিয়মিত ব্যায়াম ও খেলাধুলা করা\nপ্রতিদিন পর্যাপ্ত ঘুম ও বিশ্রাম নেওয়া\nপরিষ্কার-পরিচ্ছন্ন থাকা\nভয়, দুঃশ্চিন্তা বা সমস্যার সময় পরিবার ও শিক্ষকের সঙ্গে কথা বলা\nমোবাইল কম ব্যবহার করে পড়াশোনা ও ভালো কাজে মনোযোগ দেওয়া\nইতিবাচক চিন্তা করা এবং খারাপ সঙ্গ এড়িয়ে চলা"},{"n":"২","q":"ছেলেদের মধ্যে বয়ঃসন্ধিকালে যেসব পরিবর্তন দেখা দেয়, সেগুলো লেখ।","a":"বয়ঃসন্ধিকালে ছেলেদের মধ্যে বেশকিছু পরিবর্তন লক্ষ্য করা যায়। নিচে এগুলো লেখা হলো:\nউচ্চতা দ্রুত বৃদ্ধি পায়\nকণ্ঠস্বর ভারী হয়ে যায়\nগোঁফ-দাড়ি গজাতে শুরু করে\nপেশি শক্তিশালী হয়\nকাঁধ চওড়া হয়\nশরীরে ঘাম ও তেলের পরিমাণ বাড়ে"}],"essay":[{"n":"১","q":"'বয়ঃসন্ধিকালীন পরিবর্তন একজন শিশুর বড়ো হয়ে উঠার স্বাভাবিক প্রক্রিয়া'-ব্যাখ্যা করো।","a":"বয়ঃসন্ধিকাল মানুষের জীবনের একটি গুরুত্বপূর্ণ পর্যায়, যখন শরীর, মন এবং আচরণে বেশ কিছু পরিবর্তন দেখা দেয়। এ সময় একজন শিশুর দেহ ধীরে ধীরে প্রাপ্তবয়স্ক হওয়ার প্রস্তুতি নেয়। উচ্চতা দ্রুত বাড়া, কণ্ঠস্বরের পরিবর্তন, পেশি শক্তিশালী হওয়া, শরীরের গঠন পরিবর্তন-এসবই স্বাভাবিক শারীরিক পরিবর্তন। সেই সঙ্গে মানসিক পরিবর্তন যেমন-আত্মবিশ্বাস বৃদ্ধি, চিন্তাভাবনা পরিপক্ব হওয়া এবং আবেগের ওঠানামাও ঘটে।\nএই পরিবর্তনগুলো হঠাৎ হলেও এগুলো সম্পূর্ণ স্বাভাবিক এবং প্রত্যেক মানুষের জীবনেই ঘটে। এগুলো কখনো অসুস্থতার লক্ষণ নয়, বরং দেহের স্বাভাবিক বৃদ্ধি ও হরমোনের কার্যক্রমের ফল। তাই বয়ঃসন্ধিকাল একজন শিশুর বড়ো হয়ে ওঠার একটি স্বাভাবিক, স্বাস্থ্যকর এবং প্রয়োজনীয় ধাপ।"},{"n":"২","q":"বয়ঃসন্ধিকালে সুষম ও পুষ্টিসমৃদ্ধ খাদ্য গ্রহণ গুরুত্বপূর্ণ কেন?","a":"বয়ঃসন্ধিকালে শরীরের বৃদ্ধি অত্যন্ত দ্রুত ঘটে। উচ্চতা বাড়া, হাড়ুপেশি মজবুত হওয়া, রক্ত বৃদ্ধি, হরমোনের পরিবর্তন-এসবের জন্য দেহে অতিরিক্ত পুষ্টির প্রয়োজন হয়। সুষম খাদ্যে শর্করা, আমিষ, চর্বি, ভিটামিন, খনিজ লবণ ও পানি থাকে, যা শরীরের সঠিক বৃদ্ধি ও বিকাশ নিশ্চিত করে।\nএই সময়ে যদি সঠিক পুষ্টি না পাওয়া যায়, তবে দুর্বলতা, রক্তস্বল্পতা, উচ্চতা কম হয়ে যাওয়া, মনোযোগের ঘাটতি, রোগ প্রতিরোধ ক্ষমতা কমে যাওয়ার মতো সমস্যা দেখা দিতে পারে। সুষম খাদ্য বয়ঃসন্ধিকালীন মানসিক স্বাস্থ্যের জন্যও গুরুত্বপূর্ণ-এটি মনোযোগ বাড়ায়, ক্লান্তি কমায় এবং মানসিক স্থিতিশীলতা বজায় রাখতে সাহায্য করে।\nতাই বলা যায়, বয়ঃসন্ধিকালে সুষম ও পুষ্টিসমৃদ্ধ খাদ্য গ্রহণ সুস্থ দেহ, সুস্থ মন এবং সঠিক বৃদ্ধি নিশ্চিত করার জন্য অত্যন্ত গুরুত্বপূর্ণ।"}]}},{"no":5,"title":"অধ্যায় ৫","q":{"mcq":[{"n":"ক","q":"কোন অবস্থায় অণুগুলির মধ্যে আকর্ষণ শক্তি সবচেয়ে শক্তিশালি হয়?","a":"খ) কঠিন পদার্থ","o":["মিশ্রণ","কঠিন পদার্থ","তরল পদার্থ","গ্যাসীয় পদার্থ"]},{"n":"খ","q":"পানির কঠিন অবস্থা কোনটি?","a":"খ) বরফ","o":["পানি","বরফ","জলীয়বাষ্প","শিশির"]},{"n":"গ","q":"শরবত থেকে চিনি পৃথক করার জন্য কোনটি ব্যবহার করবে?","a":"ঘ) তাপ","o":["বাতাস","চুম্বক","ছাঁকনি","তাপ"]},{"n":"ঘ","q":"কোনো দ্রব্য ব্যবহারের পর ফেলে না দিয়ে পুনর্ব্যবহার করলে—","a":"খ) পরিবেশ ভালো থাকে","o":["অতিরিক্ত অর্থ ব্যয় হয়","পরিবেশ ভালো থাকে","পরিবেশ নষ্ট হয়","সময় নষ্ট হয়"]}],"blank":[{"n":"ক","q":"হাইড্রোজেনের একটি অণুতে ______ পরমাণু থাকে।","a":"দুইটি"},{"n":"খ","q":"পদার্থের ______ অবস্থায় অণুসমূহ সবচেয়ে দূরে দূরে থাকে।","a":"গ্যাসীয়"},{"n":"গ","q":"পানি খাওয়ার জন্য নিরাপদ করতে ______ ব্যবহার করি।","a":"ফিল্টার"},{"n":"ঘ","q":"পানির একটি অণুতে ______ হাইড্রোজেন পরমাণু আছে।","a":"দুইটি"}],"short":[{"n":"ক","q":"পানির অবস্থা কয়টি? তাদের নাম কী কী?","a":"পানির অবস্থা তিনটি। সেগুলো হলো—\nকঠিন অবস্থা (যেমন—বরফ)\nতরল অবস্থা (যেমন—পানি)\nগ্যাসীয় অবস্থা (যেমন—জলীয়বাষ্প)"},{"n":"খ","q":"পরমাণু ও অণুর মধ্যে দুইটি পার্থক্য লেখো।","a":"নিচে পরমাণু ও অণুর মধ্যে দুইটি পার্থক্য লেখা হলো—\nপরমাণু | অণু; পরমাণু হলো পদার্থের ক্ষুদ্রতম কণা যা রাসায়নিকভাবে ভাগ করা যায় না। | অণু হলো দুই বা ততোধিক পরমাণুর রাসায়নিক বন্ধনে যুক্ত রূপ।; একটি পরমাণু একা একা থাকতে পারে। | অণু সবসময় একাধিক পরমাণু নিয়ে গঠিত হয়।"},{"n":"গ","q":"পদার্থের তরল অবস্থার দুটি বৈশিষ্ট্য লেখো।","a":"পদার্থের তরল অবস্থার দুটি বৈশিষ্ট্য হচ্ছে—\nতরলের নিজস্ব আকার থাকে না, পাত্রের আকার ধারণ করে।\nতরলের আয়তন নির্দিষ্ট থাকে এবং অণুগুলোর মধ্যকার দূরত্ব মাঝারি হয়, ফলে তারা প্রবাহিত হতে পারে।"}],"essay":[{"n":"ক","q":"অণুর ধারণায় পদার্থের তিন অবস্থা ব্যাখ্যা করো।","a":"পদার্থ তিন অবস্থায় থাকে—কঠিন, তরল ও গ্যাসীয়। এ অবস্থার পার্থক্য মূলত অণুগুলোর বিন্যাস ও গতির ওপর নির্ভর করে।\nকঠিন পদার্থ: কঠিন অবস্থায় অণুগুলো খুব ঘনভাবে একে অপরের পাশে থাকে এবং তাদের মধ্যে আকর্ষণ শক্তি সবচেয়ে বেশি। তাই কঠিন পদার্থের নিজস্ব আকার ও আয়তন থাকে। যেমন—বরফ, পাথর।\nতরল পদার্থ: তরলের অণুগুলো কঠিনের তুলনায় কিছুটা দূরে থাকে এবং আকর্ষণ শক্তি মাঝারি। তাই তরল পাত্রের আকার ধারণ করে, কিন্তু আয়তন নির্দিষ্ট থাকে। যেমন—পানি, তেল।\nগ্যাসীয় পদার্থ: গ্যাসের অণুগুলো সবচেয়ে দূরে থাকে এবং তাদের মধ্যে আকর্ষণ শক্তি খুবই কম। অণুগুলো চারদিকে দ্রুত ছড়িয়ে পড়ে। এজন্য গ্যাসের নির্দিষ্ট আকার বা আয়তন নেই। যেমন—জলীয়বাষ্প, অক্সিজেন।"},{"n":"খ","q":"বাসাবাড়ির বর্জ্য পদার্থ থেকে পরিবেশ দূষণ কমানোর জন্য কী কী করা যায়?","a":"পরিবেশ দূষণ কমানোর জন্য বাসাবাড়ির বর্জ্য পদার্থ ব্যবস্থাপনায় কয়েকটি গুরুত্বপূর্ণ পদক্ষেপ নেওয়া যায়—\nবর্জ্য আলাদা করা: জৈব, পুনর্ব্যবহারযোগ্য (প্লাস্টিক, কাগজ, কাচ) এবং অ-পুনর্ব্যবহারযোগ্য বর্জ্য আলাদা করে ফেলা।\nজৈব বর্জ্য কম্পোস্ট তৈরি: রান্নাঘরের সবজি খোসা, ফলের খোসা ইত্যাদি থেকে কম্পোস্ট সার তৈরি করা।\nপ্লাস্টিক পুনর্ব্যবহার: পানির বোতল, প্যাকেট বা প্লাস্টিক সামগ্রী পুনর্ব্যবহার বা পুনঃব্যবহার করা।\nকাগজ ও পিচবোর্ড রিসাইকেল করা: পুরনো বই, খাতা, কার্টন সংগ্রহ করে পুনর্ব্যবহারে দেওয়া।\nবর্জ্য যত্রতত্র না ফেলা: বাসা ও আশপাশ পরিষ্কার রাখা ও নির্দিষ্ট ডাস্টবিনে বর্জ্য ফেলা।\nকম ব্যবহার, পুনরায় ব্যবহার: অপ্রয়োজনীয় জিনিস কম ব্যবহার করা এবং পুনর্ব্যবহারযোগ্য জিনিস বারবার ব্যবহার করা।"},{"n":"গ","q":"চিনির শরবতে ময়লা থাকলে সেই মিশ্রণ থেকে উপাদানসমূহ কীভাবে আলাদা করা যায়?","a":"চিনির শরবতে ময়লা থাকলে ছাঁকনি ব্যবহার করে মিশ্রণ আলাদা করা যায়।\nপ্রক্রিয়া: প্রথমে একটি ছাঁকনি বা পরিষ্কার কাপড় নিতে হবে। শরবতটি ছাঁকনিতে ঢাললে ময়লা ছাঁকনির ওপর আটকে যাবে, আর চিনির শরবত নিচে পরিষ্কারভাবে বেরিয়ে আসবে। প্রয়োজন হলে আরও একবার ছেঁকে নেওয়া যায়। এই পদ্ধতিকে ছাঁকন পদ্ধতি বলা হয়, যা তরল মিশ্রণ থেকে কঠিন ময়লা আলাদা করতে ব্যবহৃত হয়।"}]}},{"no":6,"title":"অধ্যায় ৬","q":{"blank":[{"n":"ক","q":"শক্তি হলো কাজ করার ______।","a":"সামর্থ"},{"n":"খ","q":"যান্ত্রিক শক্তি হলো ______ শক্তির যোগফল।","a":"গতি ও স্থিতি"},{"n":"গ","q":"তাপের চলার প্রক্রিয়াই হলো ______।","a":"তাপ সঞ্চালন"},{"n":"ঘ","q":"কঠিন পদার্থের মধ্য দিয়ে তাপ সঞ্চালিত হয় ______ পদ্ধতিতে।","a":"পরিবহন"}],"truefalse":[{"n":"১","q":"তাল পাতার তৈরি চরকি বাতাসের সাহায্যে ঘুরানোর সময় তাপশক্তি ব্যবহৃত হয়।","a":"অশুদ্ধ"},{"n":"২","q":"খাবার, জ্বালানি তেল, কয়লা ইত্যাদি রাসায়নিক শক্তির উৎস।","a":"শুদ্ধ"},{"n":"৩","q":"পরিচলন পদ্ধতিতে তরল ও বায়বীয় মাধ্যমে তাপের সঞ্চালন হয়।","a":"শুদ্ধ"},{"n":"৪","q":"সূর্য থেকে পরিবহণ পদ্ধতিতে পৃথিবীতে আলো আসে।","a":"অশুদ্ধ"},{"n":"৫","q":"শক্তির পুনর্ব্যবহার করলে শক্তি সংরক্ষণ করা যায়।","a":"শুদ্ধ"}],"short":[{"n":"ক","q":"শক্তির বিভিন্ন রূপের নাম লেখো।","a":"শক্তির বিভিন্ন রূপগুলো হলো তাপশক্তি, আলোকশক্তি, বিদ্যুৎশক্তি, শব্দশক্তি, রাসায়নিক শক্তি, গতিশক্তি ও স্থিতিশক্তি। আমাদের চারপাশে শক্তি এই বিভিন্ন রূপেই বিরাজ করে।"},{"n":"খ","q":"আলো সঞ্চালনে মাধ্যমের প্রয়োজন হয় না- এই বিষয়টি আমরা কীভাবে বুঝতে পারি?","a":"সূর্য ও পৃথিবীর মাঝখানে কোনো মাধ্যম বা বায়ু নেই, তবুও সূর্য থেকে আলো ও তাপ বিকিরণ পদ্ধতিতে পৃথিবীতে পৌঁছায়। এর মাধ্যমেই বোঝা যায় যে আলো সঞ্চালনের জন্য কোনো কঠিন, তরল বা বায়বীয় মাধ্যমের প্রয়োজন হয় না।"},{"n":"গ","q":"বৈদ্যুতিক ইস্ত্রিতে শক্তির কী রূপান্তর ঘটে?","a":"বৈদ্যুতিক ইস্ত্রিতে বিদ্যুৎশক্তি সরাসরি তাপশক্তিতে রূপান্তরিত হয়। এই উৎপন্ন তাপের মাধ্যমেই আমরা কাপড় ইস্ত্রি করতে পারি।"},{"n":"ঘ","q":"কীভাবে বাসায় শক্তির অপচয় কমানো যায়?","a":"কয়েকটি উদাহরণ দাও। বাসায় শক্তির অপচয় কমাতে কাজ শেষে বাতি ও পাখার সুইচ বন্ধ রাখা উচিত। এছাড়া দিনের বেলা জানালার পর্দা সরিয়ে সূর্যের আলোর ব্যবহার এবং ব্যবহারের পর বৈদ্যুতিক সরঞ্জামগুলো আনপ্লাগ করে রাখলে শক্তির সাশ্রয় হয়।"}],"essay":[{"n":"ক","q":"'সূর্য শক্তির প্রধান উৎস'-এই কথাটি ব্যাখ্যা করো।","a":"পৃথিবীতে আমরা যত প্রকার শক্তি দেখি, তার প্রায় সবগুলোরই প্রত্যক্ষ বা পরোক্ষ উৎস হলো সূর্য। উদ্ভিদ সূর্যের আলোক শক্তি ব্যবহার করে সালোকসংশ্লেষণ প্রক্রিয়ায় নিজের খাদ্য তৈরি করে এবং এই শক্তিকে রাসায়নিক শক্তি হিসেবে জমা রাখে। মানুষ বা অন্যান্য প্রাণী যখন সেই উদ্ভিদ খাদ্য হিসেবে গ্রহণ করে, তখন সেই রাসায়নিক শক্তি তাদের দেহে স্থানান্তরিত হয়, যা ব্যবহার করে তারা শারীরিক কাজ বা গতিশক্তি অর্জন করে। এছাড়া বর্তমানে আমরা আধুনিক প্রযুক্তির মাধ্যমে সূর্যের আলোক শক্তিকে সরাসরি বিদ্যুৎ শক্তিতে রূপান্তর করে সৌর প্যানেল চালাচ্ছি। এমনকি কয়লা বা পেট্রোলিয়ামের মতো জীবাশ্ম জ্বালানিও মূলত প্রাচীনকালের উদ্ভিদের সঞ্চিত সৌর শক্তি। তাই বলা যায়, খাদ্যের রাসায়নিক শক্তি থেকে শুরু করে আধুনিক বিদ্যুৎ শক্তি-সবকিছুর পেছনেই সূর্যের ভূমিকা রয়েছে, যা সূর্যকে শক্তির প্রধান উৎস হিসেবে প্রতিষ্ঠিত করে।"},{"n":"খ","q":"আলো সোজা পথে চলে এই বিষয়টি পরীক্ষণের আলোকে ব্যাখ্যা করো।","a":"আলোর গতির একটি প্রধান ধর্ম হলো এটি সবসময় সোজা পথে চলে, যা একটি সহজ পরীক্ষার মাধ্যমে প্রমাণ করা যায়। পরীক্ষায় তিনটি সমান উচ্চতার শক্ত কাগজের মাঝখানে ছিদ্র করে সেগুলোকে একটি মোমবাতির সামনে এমনভাবে রাখা হয় যেন ছিদ্রগুলো একই সরলরেখায় থাকে। এই অবস্থায় মোমবাতিটি জ্বালালে আমরা কাগজের অপর প্রান্ত থেকে মোমবাতির আলো পরিষ্কার দেখতে পাই। কিন্তু যখনই মাঝখানের যেকোনো একটি কাগজকে কিছুটা সরিয়ে দেওয়া হয়, অর্থাৎ ছিদ্রগুলো আর একই সরলরেখায় থাকে না, তখন আলো আর দেখা যায় না। এর কারণ হলো কাগজটি আলোর পথে বাধা সৃষ্টি করে এবং আলো বক্রপথে ছিদ্রটি খুঁজে নিতে পারে না। এই পরীক্ষাটি স্পষ্টভাবে প্রমাণ করে যে আলো সরলরেখায় বা সোজা পথে চলাচল করে।"},{"n":"গ","q":"বাড়িতে আমরা কোন কাজে কোন শক্তি ব্যবহার করে থাকি, তা ছকে উপস্থাপন করো।","a":"আমরা আমাদের দৈনন্দিন গৃহস্থালি কাজ সম্পন্ন করতে বিভিন্ন প্রকার শক্তির ওপর নির্ভর করি। নিচে তার একটি ছক দেওয়া হলো:\nগৃহস্থালি কাজ | ব্যবহৃত শক্তি | ব্যাখ্যা; অন্ধকার ঘরকে আলোকিত করা | আলোক শক্তি | বৈদ্যুতিক বাল্ব বা মোমবাতি জ্বালিয়ে আমরা এই শক্তি পাই।; টেলিভিশন দেখা বা কম্পিউটার চালানো | বিদ্যুৎ শক্তি | তারের মাধ্যমে আসা বিদ্যুৎ আমাদের বিনোদন ও কাজের সরঞ্জাম চালায়।; রান্না করা বা কাপড় ইস্ত্রি করা | তাপ শক্তি | চুলা বা ইস্ত্রি থেকে পাওয়া তাপ দিয়ে রান্না ও পোশাক পরিপাটি করি।; শরীর গঠন ও চলাফেরা করা | রাসায়নিক শক্তি | খাদ্য গ্রহণের মাধ্যমে শরীরে শক্তি সঞ্চয় করি যা পরবর্তীতে যান্ত্রিক শক্তিতে রূপান্তরিত হয়।; রেডিও বা স্পিকারে গান শোনা | শব্দ শক্তি | বিদ্যুৎ শক্তি স্পিকারের মাধ্যমে শব্দ শক্তিতে পরিণত হয়।"}]}},{"no":7,"title":"অধ্যায় ৭","q":{"mcq":[{"n":"ক","q":"বল প্রয়োগের দুটি প্রধান পদ্ধতি কী?","a":"খ) টান ও ধাক্কা","o":["ঠেলা ও চাপ","টান ও ধাক্কা","ধাক্কা ও ঘর্ষণ","চাপ ও স্পর্শ"]},{"n":"খ","q":"যখন একটি মার্বেলকে আগের চেয়ে বেশি জোরে ধাক্কা দেওয়া হয়, তখন সেটির গতি কেমন হয়?","a":"গ) বেড়ে যায়","o":["কমে যায়","একই থাকে","বেড়ে যায়","থেমে যায়"]},{"n":"গ","q":"ঘাসের ওপর দিয়ে একটি বল গড়িয়ে দিলে তা তুলনামূলকভাবে কম দূরত্ব অতিক্রম করে কেন?","a":"গ) ঘাসে ঘর্ষণ বল বেশি থাকে","o":["ঘাস বলটিকে থামিয়ে দেয়","ঘাসে বল লাফিয়ে উঠে","ঘাসে ঘর্ষণ বল বেশি থাকে","ঘাস বলকে টেনে রাখে"]},{"n":"ঘ","q":"নিচের কোন কাজটি করতে গেলে পৃথিবীর আকর্ষণ বলের বিরুদ্ধে কাজ করতে হয়?","a":"গ) সিঁড়ি দিয়ে উপরে ওঠা","o":["সিঁড়ি দিয়ে নিচে নামা","ছাতা মেলে ধরা","সিঁড়ি দিয়ে উপরে ওঠা","বল মাটিতে ফেলা"]},{"n":"ঙ","q":"একটি কাঠি ও একটি পেনসিল দিয়ে পাথর তুলতে চাইলে আমরা নিচের কোন কৌশলটি ব্যবহার করব?","a":"ঘ) পেনসিলকে ভিত্তিবিন্দু বানিয়ে কাঠিকে লিভার হিসেবে ব্যবহার করা","o":["কাঠি দিয়ে সরাসরি পাথর ঠেলা","পাথরকে গড়িয়ে দূরে নেওয়া","পেনসিল ও কাঠি দিয়ে পাথর ঠেলা","পেনসিলকে ভিত্তিবিন্দু বানিয়ে কাঠিকে লিভার হিসেবে ব্যবহার করা"]}],"blank":[{"n":"ক","q":"বল প্রয়োগ করে বস্তু ______ যায়।","a":"সরানো"},{"n":"খ","q":"বলের মাত্রা যত বেশি, বস্তুর ওপর প্রভাব তত ______।","a":"বেশি"},{"n":"গ","q":"একটি বস্তুর পৃষ্ঠ যে দিকে সরে যেতে চায় তার ______ দিকে ঘর্ষণ বল কাজ করে।","a":"বিপরীত"},{"n":"ঘ","q":"পৃথিবী সকল বস্তুকে ______ দিকে টানে।","a":"নিজের"},{"n":"ঙ","q":"কাজ সহজ করার জন্য ব্যবহৃত যন্ত্রকে ______ যন্ত্র বলে।","a":"সরল"}],"short":[{"n":"ক","q":"ঘর্ষণ বল কাকে বলে?","a":"ঘর্ষণ বল হলো এমন একটি বল যা একটি বস্তুর পৃষ্ঠের ওপর দিয়ে অপর একটি বস্তুর পৃষ্ঠকে চলতে বাধা দেয়। যখন কোনো বস্তু অন্য বস্তুর সংস্পর্শে থেকে চলতে থাকে, তখন তাদের স্পর্শতলে গতির বিরুদ্ধে এই বল তৈরি হয়।"},{"n":"খ","q":"হেলানো সমতল কী?","a":"হেলানো সমতল বা র‍্যাম্প হলো একটি সরল যন্ত্র যা একটি নির্দিষ্ট কোণে ঢালু হয়ে থাকে। এটি ব্যবহার করে সরাসরি উপরে তোলার চেয়ে অনেক কম শক্তি প্রয়োগ করে ভারী বস্তুকে সহজে উপরে উঠানো যায়।"},{"n":"গ","q":"ঘর্ষণ বল না থাকলে আমাদের চলাফেরায় কী ধরনের সমস্যা হতে পারে?","a":"ঘর্ষণ বল না থাকলে আমরা রাস্তার ওপর স্থিরভাবে দাঁড়াতে বা হাঁটতে পারতাম না এবং পা পিছলে পড়ে যেতাম। এছাড়া যানবাহনের চাকা ও রাস্তার মধ্যে ঘর্ষণ না থাকলে ব্রেক কষে গাড়ি থামানো সম্ভব হতো না, ফলে দুর্ঘটনা ঘটত।"},{"n":"ঘ","q":"বাড়িতে বা আশপাশে যেকোনো দুটি সরল যন্ত্র চিহ্নিত করে সেগুলোর ব্যবহার লেখো।","a":"বাড়িতে ব্যবহৃত দুটি সরল যন্ত্র হলো কাঁচি এবং ছুরি। কাঁচি ব্যবহার করা হয় কাপড় বা কাগজ কাটার জন্য এবং ছুরি ব্যবহার করা হয় শাকসবজি বা ফলমূল কাটার কাজে।"},{"n":"৬","q":"যদি পৃথিবীর মাধ্যাকর্ষণ বল না থাকত, তাহলে আমাদের দৈনন্দিন জীবন কেমন হতো?","a":"পৃথিবীর মাধ্যাকর্ষণ বল না থাকলে কোনো বস্তুই মাটির ওপর স্থির থাকত না এবং সবকিছু মহাশূন্যে ভেসে বেড়াত। আমরা হাঁটাহাঁটি করতে পারতাম না এবং বায়ুমণ্ডল না থাকায় আমাদের বেঁচে থাকা অসম্ভব হয়ে পড়ত। পৃথিবী প্রতিটি বস্তুকে তার নিজের কেন্দ্রের দিকে টানে বলেই আমরা সব জিনিস মাটিতে পড়তে দেখি।"}],"essay":[{"n":"ক","q":"ঘর্ষণ বল ও মাধ্যাকর্ষণ বল কী? এই দুই বল কীভাবে আমাদের দৈনন্দিন জীবনে কাজ করে?","a":"ঘর্ষণ বল হলো এমন একটি বল যা একটি বস্তুর পৃষ্ঠের ওপর দিয়ে অন্য একটি বস্তুর পৃষ্ঠকে চলতে বাধা দেয়।\nযখন আমরা কোনো তলে বস্তু সরাতে চাই, তখন তাদের স্পর্শতলে গতির বিপরীত দিকে এই বল তৈরি হয়। অন্যদিকে, পৃথিবী প্রতিটি বস্তুকে তার নিজের কেন্দ্রের দিকে যে অদৃশ্য বল দ্বারা আকর্ষণ করে, তাকে মাধ্যাকর্ষণ বল বলা হয়। দৈনন্দিন জীবনে ঘর্ষণ বল আছে বলেই আমরা রাস্তায় পিছলে না গিয়ে হাঁটতে পারি, কলম দিয়ে কাগজে লিখতে পারি এবং দিয়াশলাইয়ের কাঠি জ্বালাতে পারি। মাধ্যাকর্ষণ বলের কারণেই আমরা পৃথিবীর বুকে দাঁড়িয়ে থাকতে পারছি এবং যেকোনো বস্তু ওপর থেকে ছেড়ে দিলে তা মহাশূন্যে না হারিয়ে সরাসরি মাটির দিকে পড়ে যায়। এই দুই বল ছাড়া আমাদের স্বাভাবিক চলাফেরা এবং অস্তিত্ব বজায় রাখা অসম্ভব হতো।"},{"n":"খ","q":"মসৃণ এবং অমসৃণ পৃষ্ঠে বল গড়িয়ে দেওয়ার ফলে বলটি ভিন্ন ভিন্ন দূরত্ব অতিক্রম করে। এর কারণ ব্যাখ্যা করো।","a":"মসৃণ এবং অমসৃণ পৃষ্ঠে বলের ভিন্ন দূরত্ব অতিক্রম করার প্রধান বৈজ্ঞানিক কারণ হলো ঘর্ষণ বলের তারতম্য। মসৃণ মেঝে বা পৃষ্ঠের তলগুলো বেশ সমান থাকে, ফলে সেখানে গতির বিপরীতে কাজ করা ঘর্ষণ বল অনেক কম হয়। একারণে বলটি অনেক দূর পর্যন্ত গড়িয়ে যায় এবং থামতে বেশি সময় নেয়। কিন্তু খেলার মাঠ বা ঘাসের মতো অমসৃণ পৃষ্ঠ অনেক বেশি খসখসে হয়, যার ফলে সেখানে প্রবল ঘর্ষণ বল উৎপন্ন হয়। এই শক্তিশালী বাধা বলের গতিকে দ্রুত কমিয়ে দেয় এবং বলটি অল্প দূরত্ব অতিক্রম করেই থেমে যায়। সুতরাং, পৃষ্ঠ যত মসৃণ হবে ঘর্ষণ তত কম হবে এবং বস্তু তত বেশি দূরত্ব অতিক্রম করবে।"},{"n":"গ","q":"একটি ভারী পাথর উঠাতে বলা হলো, তাহলে আমরা কোন ধরনের সরল যন্ত্র ব্যবহার করব? কেন?","a":"একটি ভারী পাথর উঠানোর জন্য সবচেয়ে কার্যকর সরল যন্ত্র হলো 'লিভার'। লিভারের পরীক্ষায় দেখা গেছে যে, একটি নির্দিষ্ট ভিত্তি বা পেন্সিলের সাহায্যে খুব সামান্য শক্তি প্রয়োগ করে অনেক ভারী বস্তু সহজেই তোলা সম্ভব হয়। আমরা এটি ব্যবহার করব কারণ লিভার আমাদের যান্ত্রিক সুবিধা প্রদান করে, যা আমাদের পেশিশক্তির চেয়ে অনেক গুণ বেশি বল তৈরি করতে পারে। যদি আমরা ভিত্তিটিকে বা ফলক্রামকে পাথরের যত কাছে রাখব, পাথরটি সরানো তত বেশি সহজ হবে। সরল যন্ত্র আমাদের কাজকে সহজ, দ্রুত এবং কার্যকর করে তোলে বলে ভারী কাজের জন্য লিভার ব্যবহার করা সবচেয়ে বুদ্ধিমানের কাজ।"},{"n":"ঘ","q":"মনে করো, বিদ্যালয়ের বিজ্ঞান মেলায় 'ঘর্ষণ বল' ও 'মাধ্যাকর্ষণ বল' নিয়ে একটি প্রদর্শনী করতে হবে। দুটি বলের বৈশিষ্ট্য ও","a":"পার্থক্য দর্শকদের সামনে উপস্থাপন করার জন্য একটি পরিকল্পনা লেখো।\nবিদ্যালয়ের বিজ্ঞান মেলায় প্রদর্শনীটি আকর্ষণীয় করতে আমি দুটি পৃথক বিভাগ বা জোন তৈরি করব। প্রথম বিভাগে 'ঘর্ষণ বল' বোঝানোর জন্য একটি মসৃণ টাইলস এবং একটি অমসৃণ কাঠের তক্তা রাখব, যার ওপর দিয়ে ছোট গাড়ি চালিয়ে দর্শকদের ঘর্ষণের পার্থক্য দেখাব। সেখানে একটি চার্ট থাকবে যেখানে চাকার খাঁজকাটা হওয়ার কারণ এবং ঘর্ষণের সুবিধা-অসুবিধা লেখা থাকবে।\nদ্বিতীয় বিভাগে 'মাধ্যাকর্ষণ বল' প্রদর্শনের জন্য একটি উচ্চতা থেকে বিভিন্ন ওজনের বস্তু যেমন-বল, পেন্সিল ও পালক ফেলে দেখাব যে সবই মাটির দিকে পড়ছে। দর্শকদের বোঝাব যে, ঘর্ষণ বল কেবল সংস্পর্শে থাকলে কাজ করে কিন্তু মাধ্যাকর্ষণ বল বস্তু থেকে দূরে থাকলেও কাজ করে। পরিশেষে, একটি তুলনামূলক তালিকার মাধ্যমে দর্শকদের সামনে এই দুই প্রাকৃতিক বলের গুরুত্ব তুলে ধরব।"}]}},{"no":8,"title":"অধ্যায় ৮","q":{"mcq":[{"n":"ক","q":"চাষাবাদের জন্য উপযোগী ভূমিরূপ কোনটি?","a":"গ) সমভূমি","o":["পর্বত","পাহাড়","সমভূমি","মালভূমি"]},{"n":"খ","q":"মালভূমি হলো-","a":"খ) উপরিভাগ সমতল, সামান্য ঢেউ খেলানো","o":["খাড়া ঢালবিশিষ্ট উঁচু ভূমি","উপরিভাগ সমতল, সামান্য ঢেউ খেলানো","নদীবাহিত পলিমাটি দিয়ে গঠিত","সমুদ্রপৃষ্ঠ হতে কিছু উপরে অবস্থিত"]},{"n":"গ","q":"ভূমিরূপ পরিবর্তনের প্রাকৃতিক কারণ কোনটি?","a":"খ) আগ্নেয়গিরির অগ্ন্যুৎপাত","o":["নদীতে বাঁধ নির্মাণ","আগ্নেয়গিরির অগ্ন্যুৎপাত","বনাঞ্চল ধ্বংস করা","ভাঁটায় ইট পোড়ানো"]},{"n":"ঘ","q":"অনিয়ন্ত্রিত নদী খননের ফলে কোনটি ঘটে?","a":"খ) নদীভাঙন বৃদ্ধি পেতে পারে","o":["নদীতীরের ভূমিক্ষয় রোধ হয়","নদীভাঙন বৃদ্ধি পেতে পারে","নদীর নাব্য বৃদ্ধি পায়","নদীর গতিপ্রবাহ ঠিক থাকে"]}],"blank":[{"n":"ক","q":"পাহাড় ধ্বংসের মূল কারণ ______।","a":"পাহাড় কাটা"},{"n":"খ","q":"ভূমির পরিবর্তন রোধ ও সংরক্ষণে সকলের মধ্যে ______ সৃষ্টি জরুরি।","a":"সচেতনতা"},{"n":"গ","q":"কলকারখানার বর্জ্য নদীতে ফেললে ______ ঘটে।","a":"পানিদূষণ"},{"n":"ঘ","q":"______ ভূমিরূপ পরিবর্তনের অন্যতম প্রাকৃতিক কারণ।","a":"নদীভাঙ্গন"}],"short":[{"n":"ক","q":"পাহাড়ের ঢালে চাষের ফলে পাহাড়ি ভূমিরূপের কী ধরনের পরিবর্তন হতে পারে? ব্যাখ্যা করো।","a":"পাহাড়ের ঢালে চাষের ফলে মাটির উপরিভাগের স্তর আলগা হয়ে যায়, যা বৃষ্টির পানিতে খুব সহজে ক্ষয়প্রাপ্ত হয়। এর ফলে অনেক সময় মারাত্মক পাহাড় ধস ঘটে এবং ভূমির প্রাকৃতিক গঠন বা ঢালের পরিবর্তন হয়।"},{"n":"খ","q":"ভূমিরূপ পরিবর্তনের মানবসৃষ্ট দুটো কারণ লেখো।","a":"ভূমিরূপ পরিবর্তনের অন্যতম প্রধান দুটি মানবসৃষ্ট কারণ হলো নির্বিচারে পাহাড় কাটা এবং ঘরবাড়ি বা রাস্তা তৈরির জন্য বনভূমি উজাড় করা। এছাড়াও শিল্পায়ন ও জলাভূমি ভরাট করার মাধ্যমেও ভূমির প্রাকৃতিক রূপ পরিবর্তিত হয়।"}],"essay":[{"n":"ক","q":"ভূমি সংরক্ষণ কাকে বলে? ভূমি ও পরিবেশ সংরক্ষণ গুরুত্বপূর্ণ কেন? ব্যাখ্যা করো।","a":"ভূমি বা পরিবেশকে ক্ষতিগ্রস্ত এবং ধ্বংস হওয়া থেকে রক্ষা করে এদের প্রাকৃতিক বৈশিষ্ট্য পুনরায় ফিরিয়ে আনার প্রক্রিয়াকে ভূমি বা পরিবেশ সংরক্ষণ বলা হয়।\nআমাদের অস্তিত্ব টিকিয়ে রাখার জন্য ভূমি ও পরিবেশ সংরক্ষণ অত্যন্ত গুরুত্বপূর্ণ। ভূমিরূপের পরিবর্তনের ফলে সারা বিশ্বে বর্তমানে পরিবেশ, বাস্তুতন্ত্র ও জলবায়ু পরিবর্তিত হয়ে চরমভাবাপন্ন পরিবেশ তৈরি হচ্ছে। এর ফলে বন্যা, খরা, প্রচণ্ড শীত, মরুঝড়, জলোচ্ছ্বাস ও দাবানলের মতো ভয়াবহ প্রাকৃতিক দুর্যোগ দেখা দিচ্ছে। যদি আমরা সময়মতো ভূমি সংরক্ষণ না করি, তবে মাটির উর্বরতা হারিয়ে যাবে, যা খাদ্য উৎপাদনে বিপর্যয় ঘটাবে।\nএছাড়া বনভূমি উজাড় হওয়ার ফলে জীববৈচিত্র‍্য ধ্বংস হবে এবং বায়ুমণ্ডলে কার্বন ডাই-অক্সাইডের পরিমাণ বেড়ে বৈশ্বিক উষ্ণায়ন দেখা দেবে।\nসুতরাং, প্রাকৃতিক দুর্যোগের ঝুঁকি কমাতে এবং ভবিষ্যৎ প্রজন্মের জন্য একটি বাসযোগ্য পৃথিবী নিশ্চিত করতে ভূমি ও পরিবেশ সংরক্ষণ করা অপরিহার্য।"},{"n":"খ","q":"মনে করো, একটি স্থানে নদী ভরাট করে পাকা রাস্তা নির্মাণ করা হলো। এমন কার্যক্রমে ঐ স্থানের ভূমিরূপ ও পরিবেশে কী ধরনের প্রভাব পড়তে পারে? ব্যাখ্যা করো।","a":"নদী ভরাট করে পাকা রাস্তা নির্মাণ করা ভূমিরূপের একটি নেতিবাচক মানবসৃষ্ট পরিবর্তন। এর ফলে ওই অঞ্চলের ভূমিরূপের যে পরিবর্তনগুলো ঘটবে তা হলো-নদীর স্বাভাবিক গতিপথ রুদ্ধ হয়ে যাবে এবং পার্শ্ববর্তী নিচু এলাকাগুলোর পানি নিষ্কাশন ব্যবস্থা বাধাগ্রস্ত হবে। পরিবেশগতভাবে এর প্রভাব হবে আরও ভয়াবহ। নদী ভরাট হওয়ার কারণে বৃষ্টির পানি নদীতে জমতে পারবে না, ফলে সামান্য বৃষ্টিতেই ওই এলাকায় দীর্ঘস্থায়ী জলাবদ্ধতা ও কৃত্রিম বন্যার সৃষ্টি হবে।\nএছাড়া নদীর বুক চিরে রাস্তা করায় ওই এলাকার জলজ বাস্তুতন্ত্র বা ইকোসিস্টেম পুরোপুরি ধ্বংস হয়ে যাবে এবং মাছসহ বিভিন্ন জলজ প্রাণীর প্রজনন ক্ষেত্র হারিয়ে যাবে। রাস্তা নির্মাণের ফলে ওই স্থানের মাটির পানি শোষণ ক্ষমতা কমে যাবে, যা ভূগর্ভস্থ পানির স্তরকে নিচে নামিয়ে দেবে। দীর্ঘমেয়াদে এটি ওই এলাকার তাপমাত্রাকে বাড়িয়ে দেবে এবং স্থানীয় জীববৈচিত্রে‍্যর ভারসাম্য নষ্ট করবে।\nপ্রাকৃতিক সম্পদকে এভাবে ধ্বংস করার ফলে পরিবেশ তার সজীবতা হারাবে এবং স্থানীয় বাসিন্দারা দীর্ঘমেয়াদী পরিবেশগত ঝুঁকিতে পড়বে।"}]}},{"no":9,"title":"অধ্যায় ৯","q":{"mcq":[{"n":"ক","q":"কলকারখানার ধোঁয়া থেকে পরিবেশের কোন উপাদান দূষিত হয়?","a":"গ) বায়ু","o":["মাটি","পানি","বায়ু","আলো"]},{"n":"খ","q":"জমিতে অতিরিক্ত সার ব্যবহার করা হলে নিচের কোনটি দূষিত হয়?","a":"ঘ) মাটি","o":["গাছপালা","পানি","বায়ু","মাটি"]},{"n":"গ","q":"নদীর পাশের শিল্পকারখানার তরল বর্জ্য পরিবেশের কোন উপাদান দূষিত করে?","a":"ক) পানি","o":["পানি","বায়ু","মাটি","বাগান"]}],"match":[{"n":"1","q":"মাটি","a":"পলিথিন"},{"n":"2","q":"পানি","a":"রাসায়নিক সার"},{"n":"3","q":"বায়ু","a":"শিল্পবর্জ্য পোড়ানো"}],"short":[{"n":"ক","q":"বিদ্যালয় এলাকার মাটি দূষিত করে এরূপ কী কী পদার্থ খুঁজে পাওয়া যায় তা লেখো।","a":"বিদ্যালয় এলাকায় সাধারণত পড়ে থাকা পলিথিন, প্লাস্টিক বর্জ্য এবং চিপস বা বিস্কুটের মোড়ক মাটি দূষিত করে। এছাড়া যত্রতত্র ফেলা ময়লা-আবর্জনা ও লোহা বা কাঁচের টুকরো মাটির স্বাভাবিক বৈশিষ্ট্য নষ্ট করে।"},{"n":"খ","q":"পানি দূষণের কারণে কীভাবে মানুষ ও অন্যান্য জীবের ক্ষতি হয়?","a":"দূষিত পানি ব্যবহারের ফলে মানুষের ডায়রিয়া বা জন্ডিসের মতো পানিবাহিত রোগ হয় এবং মাছসহ অন্যান্য জলজ প্রাণী মারা যায়। এছাড়া পানির বিষাক্ত উপাদানের কারণে জলজ বাস্তুসংস্থানের ভারসাম্য নষ্ট হয়ে জীববৈচিত্র‍্য হুমকির মুখে পড়ে।"}],"essay":[{"n":"ক","q":"পানি দূষণ কীভাবে রোধ করা যায় তা লেখো।","a":"আমাদের জীবন ও পরিবেশের জন্য পানি অপরিহার্য, তাই পানি দূষণ রোধ করা অত্যন্ত জরুরি। পানি দূষণ রোধের প্রধান উপায় হলো জলাশয়ে সরাসরি বর্জ্য ফেলা বন্ধ করা। পুকুর, খাল-বিল, নদী বা নালার পানিতে মলমূত্র ও তরল বর্জ্য ফেলা যাবে না। কলকারখানা থেকে নির্গত ক্ষতিকর রাসায়নিক বর্জ্য সরাসরি নদীতে না ফেলে তা শোধনের ব্যবস্থা করতে হবে। কৃষিকাজে অতিরিক্ত রাসায়নিক সার ও কীটনাশকের পরিবর্তে জৈব সার ব্যবহার করলে বৃষ্টির পানির সাথে মিশে নদী বা পুকুরের পানি দূষিত হওয়ার ঝুঁকি কমে। এছাড়া গৃহস্থালির ময়লা-আবর্জনা ও প্লাস্টিক পণ্য পানির উৎসে না ফেলে নির্দিষ্ট স্থানে ফেলার অভ্যাস করতে হবে। মৃত জীবজন্তু পানিতে না ফেলে মাটি চাপা দেওয়া উচিত। সর্বোপরি, সমাজের সকল স্তরের মানুষের মধ্যে পানি দূষণের কুফল সম্পর্কে সচেতনতা বৃদ্ধি করতে হবে এবং সরকারি আইন কঠোরভাবে প্রয়োগ করতে হবে।"},{"n":"খ","q":"পরিবেশ দূষণ কমানোর জন্য বাসাবাড়ির বর্জ্য কীভাবে ফেলবে তা লেখো।","a":"বাসাবাড়ির বর্জ্য সঠিক উপায়ে অপসারণ করলে পরিবেশ দূষণ অনেকাংশে কমানো সম্ভব। প্রথমত, বাসাবাড়ির ময়লা-আবর্জনা যেখানে-সেখানে বা খোলা জায়গায় না ফেলে নির্দিষ্ট স্থানে ফেলতে হবে। সবচেয়ে ভালো উপায় হলো ঢাকনাযুক্ত ডাস্টবিন ব্যবহার করা, যাতে দুর্গন্ধ ও রোগজীবাণু ছড়াতে না পারে। পচনশীল বর্জ্য (যেমন: তরকারির খোসা, খাবারের অবশিষ্টাংশ) এবং অপচনশীল বর্জ্য (যেমন: প্লাস্টিক, কাঁচ, ধাতব বস্তু) আলাদা আলাদা বিন বা পাত্রে সংগ্রহ করা উচিত। পচনশীল বর্জ্য থেকে জৈব সার তৈরি করা যেতে পারে, যা মাটির উর্বরতা বাড়াতে সাহায্য করে। অপচনশীল বস্তুগুলো রিসাইকেল বা পুনঃপ্রক্রিয়াজাত করার জন্য সংরক্ষণ করা যেতে পারে। পরিবেশ সুস্থ রাখতে বর্জ্য পদার্থ যত্রতত্র না ফেলে একটি সুশৃঙ্খল বর্জ্য ব্যবস্থাপনা পদ্ধতি অনুসরণ করা একান্ত প্রয়োজন।"},{"n":"গ","q":"প্লাস্টিক দূষণ কমাতে তুমি এবং তোমার পরিবার কী করতে পার, তার কয়েকটি উপায় লেখো।","a":"প্লাস্টিক একটি অপচনশীল পদার্থ যা মাটি ও পানিকে মারাত্মকভাবে দূষিত করে। প্লাস্টিক দূষণ কমাতে আমি এবং আমার পরিবার নিচের পদক্ষেপগুলো গ্রহণ করতে পারি:\nপ্লাস্টিক বা পলিথিন ব্যাগের পরিবর্তে পাটের ব্যাগ বা কাপড়ের ব্যাগ ব্যবহারের অভ্যাস গড়ে তুলব।\nএকবার ব্যবহারযোগ্য প্লাস্টিক (যেমন: স্ট্র, ওয়ান টাইম প্লাস্টিক কাপ বা চামচ) ব্যবহার থেকে বিরত থাকব।\nপ্লাস্টিকের বোতল বা পাত্র ফেলে না দিয়ে সেগুলো পরিষ্কার করে বারবার ব্যবহার করার চেষ্টা করব।\nব্যবহৃত প্লাস্টিক বর্জ্য মাটিতে না ফেলে নির্দিষ্ট স্থানে জমা করব যাতে সেগুলো রিসাইকেল করা যায়।\nবাড়ির আশেপাশে বা জলাশয়ে প্লাস্টিক ফেলা বন্ধ করব এবং অন্যদেরও এ বিষয়ে সচেতন করব।\nবাজারে যাওয়ার সময় নিজের বাসা থেকে স্থায়ী থলে বা ব্যাগ সাথে নিয়ে যাব।\nএভাবে সচেতন জীবনযাপনের মাধ্যমে আমরা প্লাস্টিক দূষণ মুক্ত একটি সুন্দর পরিবেশ গড়ে তুলতে পারি।"}]}},{"no":10,"title":"অধ্যায় ১০","q":{"mcq":[{"n":"ক","q":"সৌরজগতের কেন্দ্রে থাকে কোনটি?","a":"খ) সূর্য","o":["পৃথিবী","সূর্য","চাঁদ","তারা"]},{"n":"খ","q":"বাংলাদেশে যখন মধ্যরাত তখন কোন দেশে দিন?","a":"গ) যুক্তরাজ্য","o":["ভারত","পাকিস্তান","যুক্তরাজ্য","যুক্তরাষ্ট্র"]},{"n":"গ","q":"পৃথিবীর আহ্নিক গতির কারণে কোনটি ঘটে?","a":"খ) দিন-রাত","o":["পূর্ণিমা","দিন-রাত","ঋতু পরিবর্তন","অমাবস্যা"]}],"truefalse":[{"n":"ক","q":"জানুয়ারি মাসে পৃথিবীর উত্তর গোলার্ধ সূর্য থেকে দূরে থাকে।","a":"শুদ্ধ"},{"n":"খ","q":"অক্টোবর মাসের শেষে হেমন্তকাল হয়।","a":"শুদ্ধ"},{"n":"গ","q":"গ্রীষ্মকালের পরেই আসে শরৎকাল।","a":"অশুদ্ধ"},{"n":"ঘ","q":"পৃথিবীর গতি ৩ ধরনের।","a":"অশুদ্ধ"}],"short":[{"n":"ক","q":"বাংলাদেশে ঋতু কয়টি? তাদের নাম কী কী?","a":"বাংলাদেশে মোট ঋতু ছয়টি। এগুলো হলো- গ্রীষ্মকাল, বর্ষাকাল, শরৎকাল, হেমন্তকাল, শীতকাল এবং বসন্তকাল।"},{"n":"খ","q":"বাংলাদেশের বর্ষাকাল সম্পর্কে ২টি বাক্য লেখো।","a":"গ্রীষ্মকালের পরেই বাংলাদেশে বর্ষাকাল আসে এবং এই সময়ে বাতাসে প্রচুর জলীয় বাষ্প থাকায় অনেক বৃষ্টিপাত হয়। বর্ষাকালে আমাদের অঞ্চলের খাল-বিল পানিতে ভরপুর থাকে।"}],"essay":[{"n":"ক","q":"দিন ও রাত সংঘটিত হওয়ার কারণ ব্যাখ্যা করো।","a":"পৃথিবীর আহ্নিক গতির কারণে দিন ও রাত সংঘটিত হয়।\nপৃথিবী মহাকাশে স্থির নয়, বরং এটি তার নিজের অক্ষের ওপর লাটিমের মতো অনবরত পাক খাচ্ছে। এই ঘূর্ণনের সময় পৃথিবীর যে অংশটি সূর্যের দিকে থাকে বা সূর্যের সামনে আসে, সেখানে সূর্যের আলো পড়ে। সূর্যের আলো পড়ায় পৃথিবীর ওই অংশে তখন দিন হয়। অন্যদিকে, পৃথিবীর যে অংশটি সূর্যের বিপরীত দিকে থাকে, সেখানে সূর্যের আলো পৌঁছাতে পারে না। আলোর অভাবে ওই অংশটি তখন অন্ধকার থাকে এবং সেখানে রাত হয়। পৃথিবী প্রতিনিয়ত ঘুরছে বলে এই দিন ও রাতের পরিবর্তন পর্যায়ক্রমে ঘটতে থাকে। অর্থাৎ, আহ্নিক গতির ফলেই আমরা প্রতিদিন আলো ও অন্ধকারের এই চক্রটি দেখতে পাই।"},{"n":"খ","q":"পৃথিবীর কোন গতির কারণে ঋতু পরিবর্তন হয়? কারণ ব্যাখ্যা করো।","a":"পৃথিবীর বার্ষিক গতির কারণে ঋতু পরিবর্তন হয়।\nপৃথিবী তার নিজস্ব কক্ষপথে সূর্যের চারদিকে একবার ঘুরে আসতে প্রায় ৩৬৫ দিন ৬ ঘণ্টা সময় নেয়, যাকে বার্ষিক গতি বলা হয়। ঋতু পরিবর্তনের মূল কারণ হলো পৃথিবী তার অক্ষের ওপর কিছুটা হেলে থেকে সূর্যের চারদিকে ঘোরে। এর ফলে বছরের বিভিন্ন সময়ে পৃথিবীর বিভিন্ন অংশ সূর্যের দিকে হেলে থাকে অথবা সূর্য থেকে দূরে সরে যায়। যখন উত্তর গোলার্ধ সূর্যের দিকে হেলে থাকে, তখন সেখানে সূর্যরশ্মি খাড়াভাবে পড়ে এবং তাপমাত্রা বৃদ্ধি পায়, ফলে সেখানে গ্রীষ্মকাল হয়। আবার যখন উত্তর গোলার্ধ সূর্য থেকে দূরে সরে যায়, তখন সূর্যরশ্মি তির্যকভাবে পড়ে এবং তাপমাত্রা কমে গিয়ে শীতকাল আসে। এভাবেই পৃথিবীর বার্ষিক গতি ও অক্ষের হেলানো অবস্থানের কারণে ঋতু পরিবর্তিত হয়।"},{"n":"গ","q":"ঋতু পরিবর্তনে নিরাপদ জীবনযাপন কীভাবে প্রভাবিত হয়?","a":"ঋতু পরিবর্তন মানুষের নিরাপদ ও সুস্থ জীবনযাপনকে গভীরভাবে প্রভাবিত করে, কারণ প্রতিটি ঋতুর আবহাওয়া ভিন্ন হয়। নিরাপদ থাকার জন্য আমাদের ঋতুভেদে জীবনযাত্রায় পরিবর্তন আনতে হয়। যেমন-গ্রীষ্মকালে প্রচণ্ড গরমে শরীর সুস্থ রাখতে আমাদের হালকা সুতির পোশাক পরতে হয় এবং পানিশূন্যতা রোধে প্রচুর পানি ও ফলের রস পান করতে হয়। আবার বর্ষাকালে বৃষ্টির কারণে পানিবাহিত রোগের ঝুঁকি বাড়ে এবং জলাবদ্ধতা সৃষ্টি হয়, তাই এ সময় নিরাপদ পানি পান করা ও মশার বংশবিস্তার রোধে সচেতন থাকা জরুরি। শীতকালে তীব্র ঠান্ডা থেকে বাঁচতে আমরা ভারী গরম কাপড় ব্যবহার করি এবং ত্বক ও স্বাস্থ্যের বিশেষ যত্ন নিই। যদি আমরা ঋতু পরিবর্তনের সাথে তাল মিলিয়ে সঠিক খাবার, পোশাক ও স্বাস্থ্যবিধি মেনে না চলি, তবে বিভিন্ন রোগে আক্রান্ত হওয়ার সম্ভাবনা থাকে।\nসুতরাং, নিরাপদ জীবনযাপনের জন্য ঋতুভিত্তিক সতর্কতা অবলম্বন করা অত্যন্ত প্রয়োজনীয়।"}]}},{"no":11,"title":"অধ্যায় ১১","q":{"blank":[{"n":"ক","q":"বাংলাদেশের দক্ষিণ দিকে ______ অবস্থিত।","a":"বঙ্গোপসাগর"},{"n":"খ","q":"তীব্র তাপদাহের কারণে ফসল উৎপাদন ______ পায়।","a":"হ্রাস"},{"n":"গ","q":"বায়ুর আর্দ্রতা জলবায়ুর একটি ______।","a":"উপাদান"},{"n":"ঘ","q":"যত উঁচুতে উঠা যায় তাপমাত্রা তত ______।","a":"কমতে থাকে / হ্রাস পায়"}],"truefalse":[{"n":"ক","q":"শীতকালে মৌসুমি বায়ু প্রবাহিত হয়।","a":"শুদ্ধ","e":"শীতকালে উত্তর-পূর্ব মৌসুমি বায়ু প্রবাহিত হয়"},{"n":"খ","q":"স্থলভাগে ওঠার পর ঘূর্ণিঝড় ধীরে ধীরে দুর্বল হতে থাকে।","a":"শুদ্ধ","e":"স্থলভাগে জলীয় বাষ্পের জোগান বন্ধ হয়ে যাওয়ায় এটি দুর্বল হয়"},{"n":"গ","q":"বাংলাদেশের দক্ষিণাঞ্চলে খরা বেশি হয়।","a":"অশুদ্ধ","e":"সঠিক তথ্য: বাংলাদেশের উত্তর ও উত্তর-পশ্চিমাঞ্চলে খরা বেশি হয়"},{"n":"ঘ","q":"আকাশের অবস্থা দেখে আবহাওয়া সম্পর্কে জানা যায়।","a":"শুদ্ধ"}],"short":[{"n":"ক","q":"জলবায়ুর উপাদানগুলোর নাম লেখো।","a":"জলবায়ুর প্রধান উপাদানগুলো হলো:\n১. সূর্যের আলো\n২. বায়ুমণ্ডলের তাপমাত্রা\n৩. বায়ুপ্রবাহ (দিক ও তীব্রতা)\n৪. বৃষ্টিপাত বা অধঃক্ষেপণ\n৫. বায়ুর আর্দ্রতা"},{"n":"খ","q":"আবহাওয়া ও জলবায়ুর তিনটি পার্থক্য লেখো।","a":"আবহাওয়া ও জলবায়ুর মধ্যে তিনটি প্রধান পার্থক্য নিচে দেওয়া হলো:\n১. আবহাওয়া হলো কোনো নির্দিষ্ট স্থানের বায়ুমণ্ডলের সাময়িক বা প্রতিদিনের গড় অবস্থা। আর জলবায়ু হলো কোনো অঞ্চলের সাধারণত ৩০-৪০ বছরের আবহাওয়ার সামগ্রিক গড় অবস্থা।\n২. আবহাওয়া খুব দ্রুত বা অল্প সময়ের মধ্যে (যেমন—কয়েক ঘণ্টা বা এক দিনে) বদলে যেতে পারে। কিন্তু জলবায়ু সহজে বদলায় না, এটি স্থায়ীভাবে পরিবর্তিত হতে বহু বছর সময় নেয়।\n৩. আবহাওয়া কোনো একটি ছোট নির্দিষ্ট এলাকার ওপর নির্ভর করে। পক্ষান্তরে, জলবায়ু একটি বিশাল অঞ্চল বা দেশের ওপর ভিত্তি করে নির্ধারিত হয়।"},{"n":"গ","q":"কালবৈশাখী ঝড় কেন হয়?","a":"চৈত্র ও বৈশাখ মাসে (গ্রীষ্মকালে) দুপুরের পর তীব্র রোদের কারণে কোনো অঞ্চলের স্থলভাগের বাতাস প্রচণ্ড গরম ও হালকা হয়ে ওপরের দিকে উঠে যায়। ফলে ওই স্থানে একটি শূন্যস্থান বা তীব্র নিম্নচাপের সৃষ্টি হয়। তখন চারপাশের তুলনামূলক ঠান্ডা ও ভারী বাতাস ওই শূন্যস্থান পূরণের জন্য প্রচণ্ড গতিতে ধেয়ে আসে, যার ফলে কালবৈশাখী ঝড়ের সৃষ্টি হয়।"},{"n":"ঘ","q":"জলবায়ু পরিবর্তনের পাঁচটি কারণ লেখো।","a":"জলবায়ু পরিবর্তনের পাঁচটি প্রধান কারণ হলো:\n১. কলকারখানা ও যানবাহন থেকে নির্গত ক্ষতিকর গ্রিনহাউস গ্যাসের (যেমন—কার্বন ডাইঅক্সাইড) পরিমাণ বৃদ্ধি।\n২. ব্যাপক হারে বনাঞ্চল ও গাছপালা কেটে উজাড় করা (বন উজাড়করণ)।\n৩. কয়লা, খনিজ তেল ও প্রাকৃতিক গ্যাসের মতো জীবাশ্ম জ্বালানির অতিরিক্ত ব্যবহার।\n৪. রেফ্রিজারেটর বা এসি থেকে উৎপন্ন সিএফসি (CFC) গ্যাসের নির্গমন।\n৫. প্রকৃতির নিজস্ব কিছু উপাদান ও নিয়ামকের দীর্ঘমেয়াদি পরিবর্তন।"}],"essay":[{"n":"ক","q":"জলবায়ু পরিবর্তনের নিয়ামকগুলো আলোচনা করো।","a":"জলবায়ু পরিবর্তনের প্রধান নিয়ামক বা কারণগুলো নিচে আলোচনা করা হলো: ১. বৈশ্বিক উষ্ণায়ন: বায়ুমণ্ডলে তাপমাত্রা বেড়ে যাওয়া জলবায়ু পরিবর্তনের সবচেয়ে বড় নিয়ামক। ২. গ্রিনহাউস গ্যাসের আধিক্য: কলকারখানা, যানবাহন ও বিদ্যুৎ উৎপাদন কেন্দ্র থেকে নির্গত কার্বন ডাই-অক্সাইড, মিথেন ইত্যাদি গ্যাস বায়ুমণ্ডলে বৃদ্ধি পেয়ে তাপ আটকে রাখছে। ৩. বনভূমি ধ্বংস বা বৃক্ষনিধন: ব্যাপক হারে গাছপালা কাটার ফলে বাতাস থেকে কার্বন ডাই-অক্সাইড শোষণের প্রাকৃতিক প্রক্রিয়া ব্যাহত হচ্ছে, যা তাপমাত্রা বাড়িয়ে দিচ্ছে। ৪. জীবাশ্ম জ্বালানির ব্যবহার: কয়লা, পেট্রোলিয়াম ও প্রাকৃতিক গ্যাস অতিরিক্ত পোড়ানোর ফলে বায়ুমণ্ডলের উপাদানগুলোর স্বাভাবিক ভারসাম্য নষ্ট হচ্ছে।"},{"n":"খ","q":"জলবায়ু পরিবর্তনে গ্রিনহাউস প্রভাব ব্যাখ্যা করো।","a":"গ্রিনহাউস হলো কাচের তৈরি ঘর, যা তীব্র শীতের দেশে ভেতরে উত্তাপ ধরে রেখে গাছপালা বাঁচিয়ে রাখে। কাচ ভেদ করে সূর্যের আলো ও তাপ ভেতরে ঢুকতে পারলেও তা আর বের হতে পারে না। আমাদের পৃথিবীটাও ঠিক এই গ্রিনহাউসের মতো কাজ করে। পৃথিবীর বায়ুমণ্ডলে থাকা কার্বন ডাই-অক্সাইড, জলীয় বাষ্প ইত্যাদি গ্যাস একটি আস্তরণের মতো কাজ করে। সূর্যের তাপ এই গ্যাসীয় স্তর ভেদ করে পৃথিবীতে আসে, কিন্তু প্রতিফলিত হয়ে ফিরে যাওয়ার সময় এই গ্যাসগুলো তাপকে আটকে ফেলে। একেই গ্রিনহাউস প্রভাব বলে। মানুষ প্রযুক্তির অতি-ব্যবহার ও কলকারখানার মাধ্যমে বায়ুমণ্ডলে এই গ্রিনহাউস গ্যাসের পরিমাণ দিন দিন বাড়িয়ে দিচ্ছে। ফলে পৃথিবী আগের চেয়ে অনেক বেশি গরম হয়ে উঠছে, যা সরাসরি বৈশ্বিক উষ্ণায়ন ও স্থায়ী জলবায়ু পরিবর্তন ঘটাচ্ছে।"},{"n":"গ","q":"জলবায়ু পরিবর্তনে সৃষ্ট প্রাকৃতিক দুর্যোগগুলো কী কী?","a":"জলবায়ু পরিবর্তনের ক্ষতিকর প্রভাবে বাংলাদেশসহ সারা বিশ্বে নানা রকম ভয়াবহ প্রাকৃতিক দুর্যোগ দেখা দিচ্ছে। এই প্রাকৃতিক দুর্যোগগুলোর একটি তালিকা নিচে দেওয়া হলো: ১. ঘূর্ণিঝড় ও তীব্র টর্নেডো ২. আকস্মিক বন্যা ও পাহাড়ি ঢল ৩. অনাবৃষ্টি, তীব্র তাপদাহ ও খরা ৪. নদীভাঙন এবং পাহাড়ি অঞ্চলে ভূমিধস ৫. শীতকালে তীব্র শৈত্যপ্রবাহ ৬. সমুদ্রপৃষ্ঠের উচ্চতা বৃদ্ধির ফলে উপকূলীয় অঞ্চলে জলোচ্ছ্বাস এবং নোনা পানির অনুপ্রবেশ"},{"n":"ঘ","q":"জলবায়ু পরিবর্তনজনিত সমস্যা মোকাবিলায় কী কী ব্যবস্থা গ্রহণ করা উচিত তা আলোচনা করো।","a":"জলবায়ু পরিবর্তনজনিত মারাত্মক সমস্যা ও ক্ষতিকর প্রভাব মোকাবিলায় আমাদের দুই ধরনের ব্যবস্থা বা কৌশল গ্রহণ করা উচিত। এগুলো নিচে আলোচনা করা হলো:\n১. জলবায়ু পরিবর্তনের হার কমানো (Mitigation):\nজীবাশ্ম জ্বালানি যেমন- কয়লা, তেল ও গ্যাসের ব্যবহার কমিয়ে সৌরশক্তি, বায়ুশক্তি ইত্যাদি নবায়নযোগ্য শক্তির ব্যবহার বাড়াতে হবে।\nবায়ুমণ্ডলে কার্বন ডাই-অক্সাইড কমানোর জন্য ব্যাপক হারে গাছ লাগাতে হবে এবং বনায়ন সৃষ্টি করতে হবে।\nদৈনিক জীবনে শক্তির অপচয় রোধ করতে হবে (যেমন- অপ্রয়োজনে লাইট-ফ্যান বন্ধ রাখা)।\n২. জলবায়ু পরিবর্তনের সাথে খাপ খাওয়ানো বা অভিযোজন (Adaptation):\nবন্যা ও জলোচ্ছ্বাসের হাত থেকে বাঁচতে উপকূলীয় অঞ্চলে শক্তিশালী বেড়িবাঁধ নির্মাণ করতে হবে।\nদুর্যোগের পূর্বাভাস পাওয়ার সাথে সাথে আশ্রয় নেওয়ার জন্য পর্যাপ্ত সাইক্লোন সেন্টার বা আশ্রয়কেন্দ্র তৈরি করতে হবে।\nবন্যাপ্রবণ এলাকায় ভাসমান ধাপ বা মাচায় চাষাবাদ (ভাসমান কৃষি) এবং উঁচু স্থানে ঘরবাড়ি তৈরি করতে হবে।\nজলবায়ুর পরিবর্তনের সাথে টিকে থাকতে পারে এমন খরা-সহনশীল বা লবণাক্ততা-সহনশীল নতুন জাতের ফসল উদ্ভাবন ও চাষ করতে হবে।"}]}},{"no":12,"title":"অধ্যায় ১২","q":{"mcq":[{"n":"ক","q":"ইঞ্জেকশন বা ভ্যাকসিন দ্রুত হাসপাতালে পৌঁছে দিতে ব্যবহৃত যন্ত্র কোনটি?","a":"খ) ড্রোন","o":["রোবোট","ড্রোন","অ্যাম্বুলেন্স","মোটরসাইকেল"]},{"n":"খ","q":"কেন আমরা কৃষি প্রযুক্তিতে আর্টিফিশিয়াল ইন্টেলিজেন্স ব্যবহার করব?","a":"ক) ফসলের রোগ ও সঠিক তথ্য জানতে","o":["ফসলের রোগ ও সঠিক তথ্য জানতে","ফসল সংগ্রহ করতে","জমিতে সার দিতে","শস্য রোপণ করতে"]},{"n":"গ","q":"লিবানের বাবা সৌদি আরবে গিয়েছেন। লিবান তার বাবাকে দেখতে চায় এবং তাঁর সাথে কথা বলতে চায়- এমন পরিস্থিতিতে লিবান কোনটির সহায়তা বেছে নেবে?","a":"ঘ) হোয়াটসঅ্যাপ","o":["টেলিফোন","ইমেইল","ফ্যাক্স","হোয়াটসঅ্যাপ"]}],"blank":[{"n":"ক","q":"বিশেষ বৈশিষ্ট্যসম্পন্ন উদ্ভিদ সৃষ্টিতে ব্যবহৃত হয় ______।","a":"কৃষি প্রযুক্তি / জৈব প্রযুক্তি"},{"n":"খ","q":"কম্পিউটার হলো একটি ______ যন্ত্র।","a":"ইলেকট্রনিক / গণনাকারী"},{"n":"গ","q":"এক সময় খেলাধুলার প্রচার ও বিনোদনের মাধ্যম ছিল ______।","a":"রেডিও বা বেতার"},{"n":"ঘ","q":"রোবোট পরিচালনাকারীকে উপযুক্ত ______ নিতে হবে।","a":"প্রশিক্ষণ"}],"short":[{"n":"ক","q":"শিক্ষাক্ষেত্রে ব্যবহৃত প্রযুক্তিগুলোর নাম লেখো।","a":"শিক্ষাক্ষেত্রে ব্যবহৃত প্রধান প্রযুক্তিগুলো হলো—কাগজ, কলম, পাঠ্যবই, চক, ব্ল্যাকবোর্ড, কম্পিউটার, মাল্টিমিডিয়া প্রজেক্টর, ইন্টারনেট, ই-বুক (E-book), শিক্ষণীয় মোবাইল অ্যাপ এবং কৃত্রিম বুদ্ধিমত্তা বা এআই (AI)।"},{"n":"খ","q":"কীভাবে এআই (AI)-এর নিরাপদ ব্যবহার করা যায়?","a":"এআই (AI)-এর নিরাপদ ব্যবহার নিশ্চিত করতে আমাদের সবসময় সতর্ক, দায়িত্বশীল এবং নৈতিক হতে হবে। কোনো ভুল তথ্য তৈরি করা, সাইবার অপরাধ করা বা অন্যের ক্ষতি করার মতো নেতিবাচক কাজে এআই-কে ব্যবহার করা থেকে সম্পূর্ণ বিরত থাকতে হবে। ব্যক্তিগত গোপনীয়তা ও সাইবার নিরাপত্তা রক্ষা করে কেবল শিক্ষণীয়, বৈজ্ঞানিক ও মানুষের কল্যাণমূলক কাজেই এআই-এর সাহায্য নেওয়া উচিত।"},{"n":"গ","q":"প্রযুক্তির ক্রমবিকাশ কীভাবে আমাদের জীবনযাত্রাকে সহজ করেছে?","a":"প্রযুক্তির ক্রমবিকাশের ফলে দৈনন্দিন জীবনের কঠিন কাজগুলো এখন অনেক কম বল ও সময় প্রয়োগ করে সহজে, দ্রুত ও নিখুঁতভাবে সম্পন্ন করা যাচ্ছে। যাতায়াত ব্যবস্থায় মেট্রোরেল বা আধুনিক গাড়ি, চিকিৎসায় আধুনিক রোগ নির্ণয় পদ্ধতি এবং কৃষিতে ট্রাক্টর বা কম্বাইন হারভেস্টরের মতো উন্নত প্রযুক্তির উদ্ভাবন মানুষের শ্রম কমিয়ে দৈনন্দিন জীবনকে বহুগুণ আরামদায়ক ও গতিশীল করেছে।"},{"n":"ঘ","q":"কম্পিউটারে ছবি দেখা না গেলে এর কোন অংশটি কাজ করছে না বলে ধরে নিতে হবে?","a":"কম্পিউটারে কোনো তথ্য, লেখা, ছবি বা ভিডিও যদি স্ক্রিনে দেখা না যায়, তবে কম্পিউটারের 'মনিটর' (Monitor) অংশটি কাজ করছে না বলে ধরে নিতে হবে। কারণ মনিটর হলো কম্পিউটারের প্রধান আউটপুট বা দৃশ্যমান ফলাফল প্রদর্শনকারী ডিভাইস, যার মূল কাজই হলো চিত্র বা ফলাফল ব্যবহারকারীর সামনে তুলে ধরা।"}],"essay":[{"n":"ক","q":"কম্পিউটারের প্রধান অংশগুলোর কাজ বর্ণনা করো।","a":"কম্পিউটার মূলত কয়েকটি প্রধান অংশের সমন্বয়ে গঠিত। কম্পিউটারের এই প্রধান অংশগুলোর কাজ নিচে বর্ণনা করা হলো:\n১. ইনপুট ইউনিট (Input Unit): এর কাজ হলো কম্পিউটারে বিভিন্ন উপাত্ত বা ডাটা ও নির্দেশ প্রবেশ করানো। যেমন- কিবোর্ড ও মাউস।\n২. প্রসেসিং ইউনিট বা সিপিইউ (Processing Unit / CPU): একে কম্পিউটারের মস্তিষ্ক বলা হয়। ইনপুট ইউনিট থেকে পাওয়া উপাত্তগুলোকে প্রসেস বা বিশ্লেষণ করা এবং গাণিতিক হিসাব-নিকাশ সম্পন্ন করা এর প্রধান কাজ।\n৩. মেমোরি বা স্টোরেজ ইউনিট (Memory Unit): এর কাজ হলো কম্পিউটারের প্রয়োজনীয় তথ্য ও উপাত্তগুলোকে ভবিষ্যতে ব্যবহারের জন্য স্থায়ী বা অস্থায়ীভাবে সংরক্ষণ করে রাখা।\n৪. আউটপুট ইউনিট (Output Unit): প্রসেসিং ইউনিট থেকে পাওয়া ফলাফলকে ব্যবহারকারীর কাছে দৃশ্যমান বা প্রকাশ করা এর কাজ। যেমন- মনিটর ও প্রিন্টার।"},{"n":"খ","q":"ভার্চুয়াল রিয়েলিটি ব্যবহারের ক্ষেত্রে কী কী সতর্কতা অবলম্বন করা উচিত?","a":"ভার্চুয়াল রিয়েলিটি (VR) একটি অত্যাধুনিক প্রযুক্তি হলেও এর অতিরিক্ত বা অসচেতন ব্যবহার স্বাস্থ্যের ক্ষতি করতে পারে। তাই এটি ব্যবহারের ক্ষেত্রে নিম্নলিখিত সতর্কতাগুলো অবলম্বন করা উচিত:\nব্যবহারের সময়সীমা নির্ধারণ: দীর্ঘসময় একটানা ভিআর (VR) ডিভাইস ব্যবহার করা উচিত নয়। মোশন সিকনেস, মাথাব্যথা বা চোখের ক্লান্তি এড়াতে প্রতি ৩০ থেকে ৬০ মিনিট পর পর অবশ্যই বিরতি নেওয়া উচিত।\nনিরাপদ স্থান নির্বাচন: ভিআর হেডসেট চোখে থাকলে আশেপাশের বাস্তব পরিবেশ দেখা যায় না। তাই হাঁটাচলা করার সময় কোনো কিছুর সাথে ধাক্কা লাগা বা পড়ে যাওয়া এড়াতে একটি নিরাপদ ও ফাঁকা জায়গায় বসে বা দাঁড়িয়ে এটি ব্যবহার করা উচিত।\nবয়সসীমা মেনে চলা: শিশুদের ক্ষেত্রে এটি ব্যবহারের সময় বড়দের নজরদারি থাকা প্রয়োজন এবং চিকিৎসকের পরামর্শ অনুযায়ী নির্দিষ্ট বয়সের নিচে শিশুদের এটি ব্যবহার করতে দেওয়া উচিত নয়।"},{"n":"গ","q":"ইনপুট ইউনিটে ব্যবহৃত যন্ত্রগুলোর কাজ সম্পর্কে লেখো।","a":"ইনপুট ইউনিটে মূলত এমন সব যন্ত্র ব্যবহার করা হয় যা কম্পিউটারকে কোনো তথ্য দিতে সাহায্য করে। নিচে এই ইউনিটে ব্যবহৃত প্রধান যন্ত্রগুলোর কাজ দেওয়া হলো:\nকিবোর্ড (Keyboard): এটি কম্পিউটারের প্রধান ইনপুট যন্ত্র। এর কাজ হলো বিভিন্ন বোতাম বা কি (Key) চেপে কম্পিউটারে অক্ষর, সংখ্যা, প্রতীক টাইপ করা এবং বিভিন্ন কমান্ড বা নির্দেশ দেওয়া।\nমাউস (Mouse): এটি একটি পয়েন্টিং ডিভাইস। স্ক্রিনের ওপর কারসর নাড়িয়ে কোনো ফোল্ডার বা প্রোগ্রাম সিলেক্ট করা, ওপেন করা এবং ক্লিক করার মাধ্যমে কম্পিউটারকে দ্রুত নির্দেশ দেওয়া এর কাজ।\nমাইক্রোফোন (Microphone): এর কাজ হলো মানুষের কণ্ঠস্বর বা যেকোনো শব্দকে অ্যানালগ থেকে ডিজিটাল উপাত্তে রূপান্তর করে কম্পিউটারে প্রবেশ করানো।\nওয়েবক্যামেরা (Webcam): এর কাজ হলো বাস্তব কোনো ছবি বা ভিডিও রেকর্ড করে সরাসরি কম্পিউটারে ইনপুট হিসেবে পাঠানো, যা ভিডিও কলের ক্ষেত্রে ব্যবহৃত হয়।"}]}},{"no":13,"title":"অধ্যায় ১৩","q":{"mcq":[{"n":"ক","q":"মানচিত্র-সংশ্লিষ্ট অ্যাপের সাহায্যে নিচের কোন কাজটি করবে?","a":"গ) স্থান চিহ্নিতকরণ","o":["ছবি আঁকা","টিকিট সংগ্রহ","স্থান চিহ্নিতকরণ","গেম খেলা"]},{"n":"খ","q":"তুমি রাতের আকাশের তারা স্পষ্টভাবে দেখতে চাও, এক্ষেত্রে নিচের কোন যন্ত্রের সাহায্য নেবে?","a":"ঘ) দূরবীক্ষণ যন্ত্র","o":["অণুবীক্ষণ যন্ত্র","আতশি কাচ","আয়না","দূরবীক্ষণ যন্ত্র"]},{"n":"গ","q":"দীর্ঘ সময় মোবাইল ব্যবহারের কারণে তোমার কী ধরনের সমস্যা হতে পারে?","a":"ক) চোখের সমস্যা","o":["চোখের সমস্যা","হাতে ব্যথা","মানসিক অস্থিরতা","বুকে ব্যথা"]}],"blank":[{"n":"ক","q":"প্রযুক্তির কল্যাণে আমরা সহজ ও ______ জীবনযাপন করি।","a":"আরামদায়ক/স্বাচ্ছন্দ্যময়"},{"n":"খ","q":"বিজ্ঞানীরা জলীয়বাষ্পের ক্ষমতাকে কাজে লাগিয়ে ______ উদ্ভাবন করেছেন।","a":"বাষ্পীয় ইঞ্জিন"},{"n":"গ","q":"প্রযুক্তির ______ ফলে স্বাস্থ্য ও সামাজিক ঝুঁকি বেড়ে যাচ্ছে।","a":"অপব্যবহারের/অতি ব্যবহারের"}],"truefalse":[{"n":"ক","q":"ইরি, ব্রি এবং বি আর ৩৩ উন্নত জাতের গম।","a":"অশুদ্ধ","e":"এগুলো উন্নত জাতের ধান"},{"n":"খ","q":"সহজে অনুমান করা যায় এমন পাসওয়ার্ড ব্যবহার করব।","a":"অশুদ্ধ","e":"কঠিন পাসওয়ার্ড ব্যবহার করা উচিত"},{"n":"গ","q":"জরুরিভবে অ্যাম্বুলেন্স সেবা পেতে ১৬২৬৩ নম্বরে কল করব।","a":"শুদ্ধ"},{"n":"ঘ","q":"ব্লক-কোড ব্যবহার করে বিভিন্ন গাণিতিক সমস্যার সমাধান করতে পারি।","a":"শুদ্ধ"}],"short":[{"n":"ক","q":"বিজ্ঞান ও প্রযুক্তি বলতে কী বোঝায়?","a":"বিজ্ঞান: বিজ্ঞান হলো প্রকৃতি সম্পর্কিত জ্ঞান যা পর্যবেক্ষণ ও পরীক্ষণের মাধ্যমে প্রাপ্ত এবং যা যাচাই করা যায়।\nপ্রযুক্তি: প্রযুক্তি হলো মানুষের জীবনের মানউন্নয়নে বিজ্ঞানের অর্জিত জ্ঞানের ব্যবহারিক প্রয়োগ বা বিভিন্ন হাতিয়ার ও যন্ত্রপাতি তৈরি করা।"},{"n":"খ","q":"রাষ্ট্রীয় পর্যায়ে আমরা প্রযুক্তিনির্ভর কী কী সেবা গ্রহণ করি?","a":"রাষ্ট্রীয় পর্যায়ে আমরা যেসব প্রযুক্তিনির্ভর সেবা গ্রহণ করি তার মধ্যে ৩টি উল্লেখযোগ্য সেবা হলো:\n১. অনলাইন পোর্টালে ডিজিটাল নাগরিক ডাটা সংরক্ষণ ও জন্ম-মৃত্যু নিবন্ধন করা।\n২. অনলাইনে জাতীয় পরিচয়পত্র (NID) তৈরি, যাচাই ও সংশোধন করা।\n৩. বিভিন্ন রাষ্ট্রীয় হটলাইন বা কল সেন্টারের (যেমন- ৯৯৯, ৩৩৩, ১০৯) মাধ্যমে জরুরি আইনি, সামাজিক ও স্বাস্থ্য সেবা গ্রহণ করা।"},{"n":"গ","q":"প্রযুক্তির অপব্যবহারে সৃষ্ট স্বাস্থ্যঝুঁকি কীভাবে কমানো যায়?","a":"প্রযুক্তির অপব্যবহারে সৃষ্ট স্বাস্থ্যঝুঁকি কমানোর উপায়গুলো হলো:\n১. মোবাইল, কম্পিউটার বা ল্যাপটপের একটানা ব্যবহার কমিয়ে দৈনিক স্ক্রিন টাইম নির্দিষ্ট বা সীমিত করা।\n২. ডিজিটাল ডিভাইসে মগ্ন না থেকে প্রতিদিন বিকেলে মাঠে শারীরিক খেলাধুলা ও ব্যায়াম করা।\n৩. রাতে ঘুমানোর অন্তত এক ঘণ্টা আগে সব ধরনের ডিজিটাল স্ক্রিন থেকে দূরে থাকা, যা অনিদ্রা ও চোখের ক্লান্তি দূর করতে সাহায্য করে।"}],"essay":[{"n":"ক","q":"দৈনন্দিন জীবনে কম্পিউটার কী কী কাজে ব্যবহৃত হয়?","a":"আধুনিক দৈনন্দিন জীবনে কম্পিউটার প্রতিটি ক্ষেত্রে ব্যবহৃত হচ্ছে। এর প্রধান কাজগুলো নিচে দেওয়া হলো:\nশিক্ষা ক্ষেত্রে: শিক্ষার্থীরা কম্পিউটারের সাহায্যে বিভিন্ন পড়াশোনার তথ্য অনুসন্ধান করতে পারে, ই-বুক পড়তে পারে এবং অনলাইন ক্লাসে যুক্ত হতে পারে।\nযোগাযোগ ও বিনোদন: ইমেইল, সামাজিক যোগাযোগ মাধ্যম ব্যবহার করে দূর-দূরান্তের মানুষের সাথে যোগাযোগ করা, সিনেমা দেখা, গান শোনা ও গেম খেলার কাজে এটি ব্যবহৃত হয়।\nঅফিস ও ব্যবসায়িক কাজ: যেকোনো দাপ্তরিক হিসাব-নিকাশ, চিঠিপত্র লেখা, ডাটাবেজ তৈরি এবং অনলাইন কেনাকাটা বা ই-কমার্সের কাজ কম্পিউটারের মাধ্যমে সম্পন্ন হয়।\nতথ্য সংরক্ষণ: আমাদের প্রয়োজনীয় বড় বড় ফাইল, ছবি বা মূল্যবান দলিলপত্র দীর্ঘদিনের জন্য নিরাপদভাবে কম্পিউটারে সংরক্ষণ করে রাখা যায়।"},{"n":"খ","q":"বিজ্ঞান ও প্রযুক্তির মধ্যে আন্তঃসম্পর্ক রয়েছে এই বিষয়টি ব্যাখ্যা করো।","a":"বিজ্ঞান ও প্রযুক্তির মধ্যে গভীর ও নিবিড় আন্তঃসম্পর্ক রয়েছে। এরা একে অপরের পরিপূরক এবং নির্ভরশীল। বিষয়টি নিচে ব্যাখ্যা করা হলো:\nবিজ্ঞানের ওপর প্রযুক্তির নির্ভরতা: বিজ্ঞান হলো প্রকৃতি সম্পর্কিত জ্ঞান যা পর্যবেক্ষণ ও পরীক্ষণের মাধ্যমে প্রাপ্ত। আর প্রযুক্তি হলো বিজ্ঞানের এই অর্জিত জ্ঞানের ব্যবহারিক প্রয়োগ। বিজ্ঞানের সূত্র ছাড়া প্রযুক্তি উদ্ভাবন অসম্ভব। যেমন- বিদ্যুৎ শক্তির বৈজ্ঞানিক নীতি ব্যবহার করে তৈরি হয়েছে বৈদ্যুতিক বাতি, টেলিভিশন বা পাখা। আবার বাষ্পীভবনের বৈজ্ঞানিক তত্ত্ব কাজে লাগিয়ে তৈরি হয়েছে রেফ্রিজারেটর।\nপ্রযুক্তির ওপর বিজ্ঞানের নির্ভরতা: বিজ্ঞানীরা যখন নতুন কোনো গবেষণা করতে যান, তখন তাদের উন্নত প্রযুক্তির তৈরি যন্ত্রপাতির প্রয়োজন হয়। যেমন- অণুবীক্ষণ যন্ত্র বা দূরবীক্ষণ যন্ত্র ছাড়া জীববিজ্ঞান বা জ্যোতির্বিজ্ঞানের অনেক সূক্ষ্ম গবেষণা সম্ভব হতো না।\nতাই বলা যায়, বিজ্ঞান নতুন জ্ঞান আবিষ্কার করে এবং প্রযুক্তি সেই জ্ঞানকে মানুষের কল্যাণে বাস্তব কাজে লাগায়।"},{"n":"গ","q":"প্রযুক্তির নিরাপদ ব্যবহারে কী কী পদক্ষেপ গ্রহণ করা যায় তা আলোচনা করো।","a":"প্রযুক্তির অপব্যবহার বা অতিরিক্ত ব্যবহার আমাদের শারীরিক ও মানসিক ক্ষতি করতে পারে। তাই প্রযুক্তির নিরাপদ ব্যবহারে নিম্নলিখিত পদক্ষেপগুলো গ্রহণ করা উচিত:\nপাসওয়ার্ডের গোপনীয়তা: আমাদের ব্যক্তিগত ডিভাইস, কম্পিউটার বা সামাজিক যোগাযোগ মাধ্যমের মূল পাসওয়ার্ড সবসময় শক্তিশালী ও গোপন রাখতে হবে, যেন অন্য কেউ অনধিকার প্রবেশ করতে না পারে।\nসময় নিয়ন্ত্রণ ও আসক্তি দূরীকরণ: প্রযুক্তির অতি-ব্যবহার বা স্ক্রিন টাইম কমাতে হবে। দিনের একটি নির্দিষ্ট সময়ের বেশি মোবাইল বা কম্পিউটারে বুঁদ হয়ে না থেকে মাঠে খেলাধুলা ও পরিবারের সাথে সামাজিক সময় কাটাতে হবে।\nতথ্য যাচাই-বাছাই করা: ইন্টারনেটে বা সোশ্যাল মিডিয়ায় কোনো খবর দেখলেই তা হুট করে বিশ্বাস বা শেয়ার করা যাবে না। তথ্যের সত্যতা নির্ভরযোগ্য উৎস থেকে নিশ্চিত হয়ে তবেই তা গ্রহণ করতে হবে।\nসিকিউরিটি সফটওয়্যার ব্যবহার: ক্ষতিকর ম্যালওয়্যার বা সাইবার আক্রমণ থেকে ডিভাইসকে নিরাপদ রাখতে নিয়মিত ভালো মানের অ্যান্টিভাইরাস ব্যবহার করা এবং ইন্টারনেট ব্রাউজ করার সময় সন্দেহজনক কোনো লিংকে ক্লিক না করা।"}]}}]};